function proposalListProgress(p){return p.progress?`<div class="compact-progress"><progress max="100" value="${Number(p.progress.percent)||0}" aria-label="Saved proposal completeness">${e(p.progress.percent)}%</progress><small>${e(p.progress.percent)}% complete</small></div>`:'';}
function proposalProgressMarkup(p){const progress=p.progress||{completed:0,total:14,percent:0,checklist:[]};return `<section class="proposal-completion" id="proposal-completion"><div class="completion-head"><strong>Saved proposal: ${e(progress.percent)}% complete</strong><small>${e(progress.completed)} of ${e(progress.total)} sections completed</small></div><progress max="100" value="${Number(progress.percent)||0}" aria-label="Saved proposal completeness">${e(progress.percent)}%</progress><details><summary>Completion checklist</summary><ul>${(progress.checklist||[]).map(item=>`<li class="${item.complete?'complete':'incomplete'}">${item.complete?'Complete':item.required===false?'Optional':'Missing'} · ${e(item.label)}</li>`).join('')||'<li>Start filling the form. The checklist updates after autosave.</li>'}</ul></details></section>`;}
function updateProposalProgress(){const current=document.querySelector('#proposal-completion');if(current&&proposalDraft){const open=current.querySelector('details')?.open,wrap=document.createElement('div');wrap.innerHTML=proposalProgressMarkup(proposalDraft);const next=wrap.firstElementChild;if(open!==undefined&&next.querySelector('details'))next.querySelector('details').open=open;current.replaceWith(next);}}
function sessionError(){const error=Error('Your session expired. Sign in with the same university account to save your entries.');error.status=401;error.code='SESSION_EXPIRED';return error;}
function showRequestError(error,activeForm=null){if(error.status===401||sessionExpired){showSessionExpired();return;}const message=error.status===403?'You do not have permission for this action. Check your assigned club role or ask SLD to update it. '+error.message:error.status===404?'This record or review workflow is unavailable. Refresh the saved record and contact SLD if it is still missing. Your entries remain on screen.':error.message;notice(message,true);const form=activeForm||document.activeElement?.closest?.('form')||document.querySelector('#reviewform')||document.querySelector('form');if(!form)return;let summary=form.querySelector('.inline-error');if(!summary){summary=document.createElement('div');summary.className='inline-error';summary.tabIndex=-1;summary.setAttribute('role','alert');form.prepend(summary);}summary.textContent=message;let focus=null;for(const [name,detail] of Object.entries(error.fields||{})){const element=Array.from(form.elements||[]).find(el=>!el.disabled&&(el.name===name||el.name?.startsWith(name+'_')));if(element){element.setAttribute('aria-invalid','true');let note=element.parentElement.querySelector('.field-error');if(!note){note=document.createElement('small');note.className='field-error';element.parentElement.append(note);}note.textContent=detail;focus??=element;}}(focus||summary).focus();}
const recoveryClubFields=['id','revision','registration_grant_id','name','category','bio','logo','semester','advisor_email','committee'];
const recoveryProposalFields=['id','revision','creation_key','club_id','title','summary','date','end_date','start_time','end_time','venue','mode','environment','nature','nature_other','cca_participants','cca_committee','duration','sdgs','collaboration','funding_source','introduction','objectives','target_count','eligibility','activities','itinerary','ict','logistics','transport','departure_time','pickup_point','return_time','return_pickup','committee','revenue','expenses','conclusion','ict_required','logistics_required','collaboration_club_ids','collaboration_other_enabled','collaboration_other'];
