function financeRecovery(record){if(!record)return null;return {id:record.id,revision:record.revision,proposal_id:record.proposal_id,variance_reason:record.variance_reason,rows:(record.rows||[]).map(row=>Object.fromEntries(['kind','description','amount','budget_ref','evidence_ids'].filter(key=>key in row).map(key=>[key,structuredClone(row[key])]))) };}
function persistRecovery(){if(!state?.user&&!recoveryOwner)return true;captureClub();captureProposal();if(typeof captureReport==='function')captureReport();if(typeof captureFinancialReport==='function')captureFinancialReport();const owner=state?.user?{id:state.user.id,email:state.user.email}:recoveryOwner;try{sessionStorage.setItem(recoveryKey,JSON.stringify({owner,club:editableRecovery(clubDraft,recoveryClubFields),proposal:editableRecovery(proposalDraft,recoveryProposalFields),view,step:proposalStep,selectedClubId,dirty,report:typeof reportRecovery==='function'?reportRecovery():null,finance:financeRecovery(typeof financeDraft==='undefined'?null:financeDraft),operation:typeof operationRecovery==='function'?operationRecovery():null}));return true;}catch{notice('The browser could not retain this draft for sign-in. Keep this page open and copy your unsaved entries before continuing.',true);return false;}}
