function deadlineExceptionForm(){if(state.user.role!=='sld')return '';const clubId=selectedClubId||state.clubs[0]?.id||'',record=(state.deadline_exceptions||[]).find(x=>(x.club_id||x.id)===clubId);return `<section class="panel settings-panel"><h2>Temporary late-submission permission</h2><p class="help">Give a selected club an expiring permission to submit within the normal lead-time window. Past event starts remain blocked.</p><form id="exceptionform"><div class="fields single"><div class="field"><label for="exception_club">Club *</label><select id="exception_club" name="club_id" required>${state.clubs.map(c=>`<option value="${e(c.id)}" ${c.id===clubId?'selected':''}>${e(c.name)}</option>`).join('')}</select></div><label class="checkoption"><input type="checkbox" id="exception_enabled" name="enabled" ${record?.enabled?'checked':''}>Enable temporary permission</label>${textfield('Reason *','reason',record?.reason||'','required')}${field('Permission expires (Malaysia time) *','expires_at',record?.expires_at?mytInput(record.expires_at):'','datetime-local','step="60"')}</div><button class="primary mt20" type="submit">Save club permission</button><small id="exception-record" class="block mt16">${record?`Recorded ${e(localTime(record.updated_at))} by ${e(record.updated_by)}`:'No permission recorded for this club.'}</small></form></section>`;}
function mytInput(value){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)),parts=Object.fromEntries(p.filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`;}
function wireDeadlineException(main){const form=main.querySelector('#exceptionform');if(!form)return;let revision=0;const load=()=>{const record=(state.deadline_exceptions||[]).find(x=>(x.club_id||x.id)===form.elements.club_id.value);revision=record?.revision||0;form.elements.enabled.checked=Boolean(record?.enabled);form.elements.reason.value=record?.reason||'';form.elements.expires_at.value=record?.expires_at?mytInput(record.expires_at):'';form.elements.expires_at.required=form.elements.enabled.checked;main.querySelector('#exception-record').textContent=record?`Recorded ${localTime(record.updated_at)} by ${record.updated_by}`:'No permission recorded for this club.';};form.elements.club_id.onchange=load;form.elements.enabled.onchange=()=>form.elements.expires_at.required=form.elements.enabled.checked;load();form.onsubmit=event=>{event.preventDefault();action(async()=>{const enabled=form.elements.enabled.checked,expiry=form.elements.expires_at.value;await api(`/api/clubs/${form.elements.club_id.value}/deadline-exception`,{enabled,reason:form.elements.reason.value,expires_at:enabled?expiry+':00+08:00':null,revision});await refresh();load();notice(enabled?'Temporary club permission recorded.':'Temporary club permission revoked.');});};}
function contactsPage(){const main=app.querySelector('main');if(state.user.role!=='sld'){main.innerHTML='<div class="info">Student contacts are available to SLD staff.</div>';return;}main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">SLD administration</div><h1>Student contacts</h1><p>Filter university directory records by programme, complete student ID, club or intake. Imported profiles are identified by their source.</p></div><button type="button" class="primary" id="importcontacts">Import directory contacts</button></header><section class="panel contact-filters"><form id="contactfilterform"><div class="fields">${field('Name / email','q',contactsFilters.q||'')}${field('Programme','programme',contactsFilters.programme||'','text','list="contact-programmes"')}${field('Complete student ID','student_id',contactsFilters.student_id||'','text','placeholder="QIU-202610-000001"')}<div class="field"><label for="contact-club">Club committee / advisor</label><select id="contact-club" name="club_id"><option value="">All university contacts</option>${state.clubs.map(c=>`<option value="${e(c.id)}" ${(contactsFilters.club_id||selectedClubId)===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select></div>${field('Intake year','intake_year',contactsFilters.intake_year||'','number','min="2000" max="2100" step="1"')}<div class="field"><label for="intake_month">Intake month</label><select id="intake_month" name="intake_month"><option value="">All months</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${String(contactsFilters.intake_month||'')===String(i+1)?'selected':''}>${new Intl.DateTimeFormat('en-MY',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1)))}</option>`).join('')}</select></div></div><div class="actions mt20"><button type="button" id="clearcontacts">Clear filters</button></div></form><datalist id="contact-programmes"></datalist></section><section class="panel"><div id="contactresults" aria-live="polite">Loading contacts…</div><div class="formfooter mt20"><small id="contactrange"></small><div class="actions"><button type="button" id="contactprevious">← Previous</button><button type="button" id="contactnext">Next →</button></div></div></section>`;main.querySelector('#importcontacts').onclick=()=>action(async()=>{const data=await api('/api/contacts/import',{});notice(`Directory import completed${typeof data.imported==='number'?': '+data.imported+' contacts':''}.`);await loadContacts();});const form=main.querySelector('#contactfilterform');wireAutoFilters(form,()=>{contactsFilters=Object.fromEntries(new FormData(form));contactsOffset=0;return loadContacts();});main.querySelector('#clearcontacts').onclick=()=>{contactsFilters={};contactsOffset=0;contactsPage();};main.querySelector('#contactprevious').onclick=()=>{contactsOffset=Math.max(0,contactsOffset-50);loadContacts().catch(showRequestError);};main.querySelector('#contactnext').onclick=()=>{contactsOffset+=50;loadContacts().catch(showRequestError);};if(!contactsFilters.club_id&&selectedClubId)contactsFilters.club_id=selectedClubId;loadContacts().catch(showRequestError);}
async function loadContacts(){const request=++contactsRequest,query=new URLSearchParams({...contactsFilters,offset:String(contactsOffset),limit:'50'}),data=await api('/api/contacts?'+query);if(request!==contactsRequest||view!=='contacts')return;const contacts=data.contacts||[],target=document.querySelector('#contactresults');target.innerHTML=contacts.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th scope="col">Student / staff</th><th scope="col">University ID</th><th scope="col">Programme / department</th><th scope="col">Intake</th><th scope="col">Profile source</th></tr></thead><tbody>${contacts.map(person=>`<tr><td><div class="identity compact">${personAvatar(person)}<div><strong>${e(person.name)}</strong><small class="block">${e(person.email)}</small></div></div></td><td>${e(person.student_id||person.university_id||'—')}${person.student_id_last4?`<small class="block">Last four: ${e(person.student_id_last4)}</small>`:''}</td><td>${e(person.programme||person.department||'—')}</td><td>${person.intake_year?e(person.intake_year)+' / '+e(String(person.intake_month).padStart(2,'0')):'Not available'}</td><td><small>${e(person.source||'Directory source not recorded')}<br>${person.imported_at?e(localTime(person.imported_at)):''}</small></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No contacts match these filters.</p>';const total=data.total||0;document.querySelector('#contactrange').textContent=total?`${contactsOffset+1}–${contactsOffset+contacts.length} of ${total} contacts`:'No matching contacts';document.querySelector('#contactprevious').disabled=contactsOffset===0;document.querySelector('#contactnext').disabled=contactsOffset+contacts.length>=total;document.querySelector('#contact-programmes').innerHTML=(data.programme_options||[]).map(p=>`<option value="${e(p)}">`).join('');wireAvatarFallbacks(target);}
function groupedActivityMarkup(groups){return groups.length?groups.map((group,index)=>`<details class="activity-group" data-group="${index}"><summary><div><strong>${e(group.title||group.summary)}</strong><small>${e(group.club_name||'System activity')} · ${e(group.record_type==='proposal'?'Event proposal':group.record_type==='club'?'Club registration':'System record')}</small></div><div><span class="badge">${e(group.count)} actions</span><small>${e(localTime(group.latest_at))}</small></div></summary><div class="activity-detail" data-group-detail="${index}"><p class="muted">Open this group to load its activity.</p></div></details>`).join(''):'<p class="muted">No activity matches this club workspace.</p>';}
async function loadActivity(){const request=++activityRequest,offset=activityOffset,target=document.querySelector('#activityresults');if(!target)return;target.setAttribute('aria-busy','true');document.querySelector('#activityprevious').disabled=true;document.querySelector('#activitynext').disabled=true;try{const query=new URLSearchParams({offset:String(offset),limit:'25',grouped:'1',club_id:selectedClubId}),data=await api('/api/activity?'+query);if(request!==activityRequest||view!=='activity'||!state.user)return;const groups=data.groups||[],total=data.total??groups.length;target.innerHTML=groupedActivityMarkup(groups);target.querySelectorAll('details[data-group]').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open&&!detail.dataset.loaded){detail.dataset.loaded='true';loadActivityGroup(groups[Number(detail.dataset.group)],detail.querySelector('[data-group-detail]'),0).catch(showRequestError);}}));document.querySelector('#activityrange').textContent=total?`${offset+1}–${offset+groups.length} of ${total} activity groups`:'No activity groups';document.querySelector('#activityprevious').disabled=offset===0;document.querySelector('#activitynext').disabled=offset+groups.length>=total;}catch(err){if(request===activityRequest){target.textContent=err.message;showRequestError(err);}}finally{target.removeAttribute('aria-busy');}}
async function loadActivityGroup(group,target,offset){target.textContent='Loading this record’s activity…';const query=new URLSearchParams({club_id:group.club_id||'',record_id:group.record_id||'',group_key:group.key,offset:String(offset),limit:'25'}),data=await api('/api/activity?'+query);if(!target.isConnected)return;const entries=data.entries||[];target.innerHTML=`<ol class="activity-timeline">${entries.map(entry=>`<li><strong>${e(entry.summary||humanAction(entry.action))}</strong><small>${e(entry.actor_name||entry.actor)} · ${e(localTime(entry.timestamp))}</small></li>`).join('')}</ol><div class="formfooter"><small>${data.total?`${offset+1}–${offset+entries.length} of ${data.total} actions`:'No recorded actions'}</small><div class="actions">${offset?'<button type="button" data-history-newer>Newer actions</button>':''}${offset+entries.length<data.total?'<button type="button" data-history-older>Older actions</button>':''}</div></div>`;target.querySelector('[data-history-newer]')?.addEventListener('click',()=>loadActivityGroup(group,target,Math.max(0,offset-25)).catch(showRequestError));target.querySelector('[data-history-older]')?.addEventListener('click',()=>loadActivityGroup(group,target,offset+25).catch(showRequestError));}
function showProposalRemoteChange(){if(document.querySelector('#proposal-remote-change'))return;const banner=document.createElement('section');banner.id='proposal-remote-change';banner.className='info';banner.setAttribute('role','status');banner.innerHTML='<p>A newer saved proposal exists. Your current entries remain here; save and signing are blocked until you review the latest version.</p><button type="button">Load latest saved version</button>';document.querySelector('#main').prepend(banner);banner.querySelector('button').onclick=()=>{if(dirty&&!confirm('Loading the latest version will discard your unsaved entries. Continue?'))return;const latest=proposalRemote;resetProposalAutosave();proposalDraft=structuredClone(latest);clearRecovery();render();};}
function committeePerson(member,club=clubDraft||clubProfile){const directory=club?.club_people?.find(p=>p.email===member.email);return directory||(state.user.email===member.email?{...member,photo:state.user.photo}:member);}
function advisorPerson(club){return club.club_people?.find(p=>p.position==='Advisor')||{email:club.advisor_email,name:club.advisor_email};}


document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&proposalDraft&&dirty){persistRecovery();flushProposal().catch(()=>{});}});
window.addEventListener('pagehide',()=>{if(!proposalDraft||!dirty)return;persistRecovery();if(proposalSavePromise||sessionExpired)return;captureProposal();const body=JSON.stringify({proposal:proposalDraft});if(new Blob([body]).size<60000)fetch('/api/proposals',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},body,keepalive:true}).catch(()=>{});});

function proposalClub(p){return [...state.clubs,...(state.event_clubs||[])].find(c=>String(c.id)===String(p.club_id));}
function proposalClubOptions(p){const clubs=state.clubs.filter(clubCanEditProposals),current=proposalClub(p);if(current&&!clubs.some(c=>c.id===current.id))clubs.push(current);return clubs;}
function proposalCanSubmit(p){return proposalCanEdit(p)&&(p.can_submit??(proposalClub(p)?.committee||[]).some(member=>member.email===state.user.email&&['President','Vice President'].includes(member.position)));}
function proposalCanManageCommittee(p){return proposalCanEdit(p)&&(p.can_manage_committee??clubCanEditProposals(proposalClub(p)));}
function normalObjectives(value){const values=Array.isArray(value)?value.slice():String(value||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);while(values.length<2)values.push('');return values;}
function objectivesEditor(){const values=normalObjectives(proposalDraft.objectives);return `<section class="field full objectives-editor"><h3>${requiredLabel('Event objectives *')}</h3><p class="help">Provide at least two objectives. The ordered list is inserted into the original proposal.</p><ol>${values.map((value,index)=>`<li><label class="sr-only" for="objective_${index}">Objective ${index+1}</label><input id="objective_${index}" name="objective_${index}" value="${e(value)}" placeholder="Objective ${index+1}"><div class="actions">${index?`<button type="button" data-objective-move="${index}" data-direction="-1" aria-label="Move objective ${index+1} up">↑</button>`:''}${index<values.length-1?`<button type="button" data-objective-move="${index}" data-direction="1" aria-label="Move objective ${index+1} down">↓</button>`:''}${values.length>2?`<button type="button" data-objective-remove="${index}" aria-label="Remove objective ${index+1}">Remove</button>`:''}</div></li>`).join('')}</ol><button type="button" id="add-objective">+ Add objective</button></section>`;}
function optionalSupport(label,key){const applicable=key==='ict'||proposalDraft.mode!=='Virtual',required=applicable&&(proposalDraft[key+'_required']??true);return `<div class="field full optional-support" data-support="${key}" ${key==='logistics'&&proposalDraft.mode==='Virtual'?'hidden':''}><label class="checkoption"><input name="${key}_required" type="checkbox" ${required?'checked':''}>${e(label)} required</label><div data-support-fields="${key}" ${required?'':'hidden'}><label for="${key}">${requiredLabel(label+' details *')}</label><textarea name="${key}" id="${key}" ${required?'required':'disabled'} placeholder="Describe the support needed">${e(proposalDraft[key]||'')}</textarea></div><small data-support-note="${key}">${required?'Describe the support needed for this event.':'Not applicable — no support requested.'}</small></div>`;}
function eventCommitteeEditor(){const manageable=proposalCanManageCommittee(proposalDraft),rows=proposalDraft.committee||[];return `<div class="event-committee"><p class="help">Select a university directory email for each event committee member. Names and IDs are supplied by the server. These members may work on this event without receiving access to the whole club.</p>${manageable?'':'<p class="help">Only the club committee or SLD can change event committee assignments.</p>'}${rows.map((member,index)=>`<fieldset class="event-officer" ${manageable?'':'disabled'}><legend>Event committee member ${index+1}</legend><div class="fields">${field('QIU directory email *',`committee_${index}_email`,member.email,'email','list="event-directory-people"')}${field('Directory name',`committee_${index}_name`,member.name,'text','readonly')}${field('University ID',`committee_${index}_university_id`,member.university_id,'text','readonly')}${field('Event role *',`committee_${index}_role`,member.role)}${textfield('Responsibility *',`committee_${index}_responsibility`,member.responsibility)}</div>${manageable?`<button type="button" class="danger mt16" data-remove-row="committee" data-index="${index}">Remove member</button>`:''}</fieldset>`).join('')||'<p class="muted">No event committee members selected.</p>'}${manageable?'<button type="button" data-add-row="committee">+ Add event committee member</button>':''}<datalist id="event-directory-people"></datalist></div>`;}
function wireProposalExtensions(main,p){main.querySelectorAll('[name=ict_required],[name=logistics_required]').forEach(toggle=>toggle.onchange=()=>{const key=toggle.name.replace('_required',''),input=main.querySelector('#'+key);if(input)input.disabled=!toggle.checked;const note=main.querySelector(`[data-support-note="${key}"]`);if(note)note.textContent=toggle.checked?'Describe the support needed before continuing.':'Not applicable — no support requested.';captureProposal();markProposalChanged();});const changeObjectives=change=>{if(!proposalCanEdit(p))return;captureProposal();change(p.objectives);markProposalChanged();render();};main.querySelector('#add-objective')?.addEventListener('click',()=>changeObjectives(values=>values.push('')));main.querySelectorAll('[data-objective-remove]').forEach(button=>button.onclick=()=>changeObjectives(values=>values.splice(Number(button.dataset.objectiveRemove),1)));main.querySelectorAll('[data-objective-move]').forEach(button=>button.onclick=()=>changeObjectives(values=>{const index=Number(button.dataset.objectiveMove),next=index+Number(button.dataset.direction);[values[index],values[next]]=[values[next],values[index]];}));if(!proposalCanEdit(p))main.querySelectorAll('#add-objective,[data-objective-remove],[data-objective-move]').forEach(el=>el.disabled=true);if(!proposalCanManageCommittee(p))return;main.querySelectorAll('input[list=event-directory-people]').forEach(input=>{let timer;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const email=input.value;if(email.length<2)return;try{const data=await api('/api/directory?q='+encodeURIComponent(email));if(!input.isConnected||input.value!==email||proposalDraft!==p)return;main.querySelector('#event-directory-people').innerHTML=(data.people||[]).map(person=>`<option value="${e(person.email)}">${e(person.name)} · ${e(person.university_id||'')}</option>`).join('');}catch(error){showRequestError(error);}},300);};input.onchange=async()=>{const email=input.value,index=Number(input.name.split('_')[1]);try{const data=await api('/api/directory?q='+encodeURIComponent(email));if(!input.isConnected||input.value!==email||proposalDraft!==p)return;const person=(data.people||[]).find(person=>person.email.toLowerCase()===email.toLowerCase());if(!person)throw Error('Select a known university directory email. Ask SLD to import or update missing contacts.');main.querySelector(`[name=committee_${index}_name]`).value=person.name||'';main.querySelector(`[name=committee_${index}_university_id]`).value=person.university_id||'';captureProposal();markProposalChanged();}catch(error){showRequestError(error);}};});}
function personalDashboard(){if(!state.clubs.length&&!state.proposals.length&&!(state.registration_grants||[]).length){document.querySelector('#main').innerHTML='<header class="pagehead"><div><div class="eyebrow">Campus information</div><h1>Student Life</h1><p>Browse approved upcoming events and ask the assistant about public campus activities. Club administration is available when you receive a committee assignment.</p></div></header>';return;}const main=app.querySelector('main'),clubs=visibleClubs(),proposals=visibleProposals(),pending=proposals.filter(p=>['pending_advisor','pending_sld'].includes(p.status)),events=proposals.filter(p=>p.status==='approved');main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">Your university workspace</div><h1>Welcome, ${e(state.user.name)}</h1><p>Review your assigned clubs and event responsibilities. Your permissions are specific to each club or event.</p></div><button type="button" id="dashboard-allproposals">View proposals</button></header><div class="stat-grid">${[['Assigned clubs',clubs.length],['Assigned proposals',proposals.length],['In review',pending.length],['Approved events',events.length]].map(([label,count])=>`<section class="stat"><small>${e(label)}</small><strong>${count}</strong></section>`).join('')}</div><div class="dashboard-grid"><section class="panel"><h2>My clubs</h2>${clubs.length?clubs.map(clubRow).join(''):'<p class="muted">No club-level assignment. Event committee access is listed separately.</p>'}${(state.registration_grants||[]).some(g=>g.status==='available')?'<button type="button" id="dashboard-register">View registration invitation</button>':''}</section><section class="panel"><h2>Assigned event work</h2>${proposals.length?proposals.map(p=>`<article class="clubrow"><div><h3>${e(p.title||'Untitled proposal')}</h3><p>${e(proposalClub(p)?.name||'Organising club')}${p.assigned_event_roles?.length?' · '+e(p.assigned_event_roles.join(', ')):''}</p>${badge(p.status)}${proposalListProgress(p)}</div><button type="button" data-dashboard-proposal="${e(p.id)}">Open event →</button></article>`).join(''):'<p class="muted">No events assigned yet.</p>'}</section></div><section class="panel"><h2>Club finances</h2><p class="help">Balances use the SLD opening balance and approved actual financial reports. Proposed event budgets do not change the balance.</p><div id="dashboard-finances">${clubs.length?'Loading approved balances…':'No club finance access.'}</div></section>`;main.querySelector('#dashboard-allproposals').onclick=()=>navigate('proposals');main.querySelector('#dashboard-register')?.addEventListener('click',()=>navigate('clubs'));wireClubOpen(main);wireDashboardProposals(main);loadDashboardFinances(clubs).catch(showRequestError);}
async function loadDashboardFinances(clubs){const target=document.querySelector('#dashboard-finances');if(!target||!clubs.length)return;const results=await Promise.allSettled(clubs.map(club=>api('/api/finance?club_id='+encodeURIComponent(club.id))));if(!target.isConnected)return;target.innerHTML=results.map((result,index)=>result.status==='fulfilled'?`<article class="finance-summary"><div><h3>${e(clubs[index].name)}</h3><small>Approved actual balance</small><strong class="balance">${money(result.value.balance)}</strong>${result.value.opening_set?'':'<small>Opening balance not yet recorded by SLD.</small>'}${activitySummaryMarkup(result.value.activity_summary)}</div><button type="button" data-dashboard-finance="${e(clubs[index].id)}">View finances</button></article>`:`<article class="finance-summary"><div><h3>${e(clubs[index].name)}</h3><p class="help">Financial records could not be loaded. Retry after checking your access or connection.</p></div></article>`).join('');target.querySelectorAll('[data-dashboard-finance]').forEach(button=>button.onclick=()=>{selectedClubId=button.dataset.dashboardFinance;navigate('finance');});}

let financeData=null,financeDraft=null,financeEventId=null,financeInfo=null,financeRevisionRequest=0,financePeriod='monthly',financeDay=null,financeHeatmapYear=null,financeEditVersion=0,financeSavedVersion=0,financeSavePromise=null,financeRemote=null,financeSaveTimer,financeSaveError='',financeUploadPromise=null,financeUploadError='';
const money=value=>new Intl.NumberFormat('en-MY',{style:'currency',currency:'MYR'}).format(Number(value)||0);
function financePage(){const main=app.querySelector('main');if(financeEventId){loadEventFinance(main,financeEventId).catch(error=>{main.innerHTML='<section class="info"><h1>Financial report unavailable</h1><p>Your local entries are retained. Check your event assignment or reconnect with the original university account.</p></section>';showRequestError(error);});return;}const clubs=visibleClubs();if(!clubs.length){main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">Assigned events</div><h1>Event financial reports</h1><p>Record actual income, expenses and receipts for an approved event you are assigned to. Club balances are restricted to club-level assignments.</p></div></header><section class="panel">${financeEventRows(visibleProposals().filter(p=>p.status==='approved'))}</section>`;wireFinanceEventLinks(main);return;}const club=clubs.find(c=>c.id===selectedClubId)||clubs[0];main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">Approved actual records</div><h1>Club finances</h1><p>${e(club.name)} · Balances change only when SLD approves actual reports.</p></div><button type="button" id="refreshfinance">Refresh records</button></header><div id="financial-workspace" aria-live="polite">Loading financial records…</div>`;main.querySelector('#refreshfinance').onclick=()=>loadClubFinance(club,main).catch(showRequestError);loadClubFinance(club,main).catch(showRequestError);}
function financeEventRows(proposals){return proposals.length?proposals.map(p=>`<article class="clubrow"><div><h3>${e(p.title)}</h3><p>${e(proposalClub(p)?.name||'Club')} · ${e(humanDate(p.date))}</p>${badge(p.status)}</div><button type="button" data-finance-event="${e(p.id)}">Open actual report</button></article>`).join(''):'<p class="muted">No approved events available for financial reporting.</p>';}
async function openEventFinance(id){await action(async()=>{await leaveCurrent();clubDraft=proposalDraft=clubProfile=null;financeDraft=null;financeEventId=id;view='finance';render({resetScroll:true,preserveFocus:false});});}
function wireFinanceEventLinks(main){main.querySelectorAll('[data-finance-event]').forEach(button=>button.onclick=()=>openEventFinance(button.dataset.financeEvent));}
async function loadClubFinance(club,main){const request=++financeRevisionRequest,data=await api('/api/finance?club_id='+encodeURIComponent(club.id));if(request!==financeRevisionRequest||view!=='finance'||!main.isConnected)return;financeData=data;const target=main.querySelector('#financial-workspace');if(!target)return;target.innerHTML=`<div class="stat-grid finance-statistics">${[['Approved balance',data.balance],['Approved actual income',data.approved_income],['Approved actual expenses',data.approved_expenses]].map(([label,value])=>`<section class="stat"><small>${e(label)}</small><strong>${money(value)}</strong></section>`).join('')}</div><div class="info">Opening balance: ${money(data.opening_balance)}${data.opening_set?' · Recorded by SLD.':' · Not yet recorded by SLD.'} Planned event budgets are shown for comparison and never added to the club balance.</div><section class="panel"><header class="section-heading"><div><h2>Income & expenses over time</h2><p class="help">Amounts from approved actual reports, grouped by the month or year when SLD posted them.</p></div><div class="actions"><button type="button" data-finance-period="monthly" aria-pressed="${financePeriod==='monthly'}">By month</button><button type="button" data-finance-period="yearly" aria-pressed="${financePeriod==='yearly'}">By year</button></div></header><div id="finance-chart">${financeChart(data[financePeriod]||[])}</div></section><section class="panel"><h2>Event budgets & actual reports</h2>${(data.events||[]).length?(data.events||[]).map(event=>`<details class="finance-event-record"><summary><strong>${e(event.title)}</strong><span class="event-status-labels"><span class="badge">Proposal: ${e(statusLabel(event.status))}</span><span class="badge">Actual report: ${e(statusLabel(event.report_status||'not_started'))}</span></span></summary><div class="fields mt20"><div><small>Planned income / expenses</small><strong class="block">${money(event.planned_income)} / ${money(event.planned_expenses)}</strong></div><div><small>Reported actual income / expenses</small><strong class="block">${money(event.actual_income)} / ${money(event.actual_expenses)}</strong></div></div><p class="help mt16">Event schedule: ${e(humanDate(event.date||'Not set'))}</p><h3 class="mt20">Approved actual transactions for this event</h3>${financeLedger((data.entries||[]).filter(row=>row.proposal_id===event.proposal_id))}<button type="button" class="mt20" data-finance-event="${e(event.proposal_id)}">View receipts & actual report</button></details>`).join(''):'<p class="muted">No approved event records yet.</p>'}</section><section class="panel"><h2>Approved transaction ledger</h2>${financeLedger(data.entries||[])}</section>${data.can_admin&&!data.opening_set?`<section class="panel settings-panel"><h2>Record opening balance</h2><p class="help">SLD records this balance once. Provide the existing club funds, not a proposed event budget.</p><form id="opening-balance-form"><div class="fields">${field('Opening amount (RM) *','amount','','number','required step="0.01"')}${field('Reason / source *','reason','','text','required')}</div><button type="submit" class="primary mt20">Record opening balance</button></form></section>`:''}`;target.querySelectorAll('[data-finance-period]').forEach(button=>button.onclick=()=>{financePeriod=button.dataset.financePeriod;target.querySelectorAll('[data-finance-period]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));target.querySelector('#finance-chart').innerHTML=financeChart(data[financePeriod]||[]);});wireFinanceEventLinks(target);const opening=target.querySelector('#opening-balance-form');if(opening)opening.onsubmit=event=>{event.preventDefault();action(async()=>{await api('/api/finance/opening',{club_id:club.id,...Object.fromEntries(new FormData(opening))});await loadClubFinance(club,main);notice('Opening balance recorded by SLD.');});};}
function financeChart(rows){if(!rows.length)return '<p class="muted">No approved actual income or expenses have been recorded in this period.</p>';const maximum=Math.max(1,...rows.flatMap(row=>[Number(row.income)||0,Number(row.expenses)||0]));return `<div class="chart-legend"><span><i class="income-dot"></i>Income</span><span><i class="expense-dot"></i>Expenses</span></div><div class="finance-bars">${rows.map(row=>`<div class="finance-bar-row"><strong>${e(humanPeriod(row.period))}</strong><div class="finance-bar-pair"><div><span class="income-bar" style="width:${Math.max(0,Number(row.income)||0)/maximum*100}%"></span><small>${money(row.income)} income</small></div><div><span class="expense-bar" style="width:${Math.max(0,Number(row.expenses)||0)/maximum*100}%"></span><small>${money(row.expenses)} expenses</small></div></div><small>Net ${money(row.net)}</small></div>`).join('')}</div>`;}
function progressChart(rows){if(!rows.length)return '<p class="muted">No scheduled proposals or recorded club actions in this period.</p>';const maximum=Math.max(1,...rows.flatMap(row=>[Number(row.scheduled_events??row.events)||0,Number(row.events)||0,Number(row.actions)||0]));return `<div class="chart-legend"><span><i class="scheduled-dot"></i>All scheduled proposals</span><span><i class="income-dot"></i>Approved events</span><span><i class="progress-actions-dot"></i>Recorded club actions</span></div><div class="finance-bars">${rows.map(row=>`<div class="finance-bar-row"><strong>${e(humanPeriod(row.period))}</strong><div class="finance-bar-pair"><div><span class="scheduled-bar" style="width:${Math.max(0,Number(row.scheduled_events??row.events)||0)/maximum*100}%"></span><small>${e(Number(row.scheduled_events??row.events)||0)} scheduled proposals, all statuses</small></div><div><span class="income-bar" style="width:${Math.max(0,Number(row.events)||0)/maximum*100}%"></span><small>${e(Number(row.events)||0)} approved events</small></div><div><span class="progress-actions-bar" style="width:${Math.max(0,Number(row.actions)||0)/maximum*100}%"></span><small>${e(Number(row.actions)||0)} recorded club actions</small></div></div></div>`).join('')}</div>`;}
function financeHeatmap(days){if(financeHeatmapYear===null)financeHeatmapYear=Number(mytParts(state.server_time||new Date().toISOString()).year);const begin=new Date(Date.UTC(financeHeatmapYear,0,1)),end=new Date(Date.UTC(financeHeatmapYear+1,0,1)),length=Math.round((end-begin)/86400000),lookup=new Map(days.map(day=>[day.date,day]));return `<header class="section-heading heatmap-heading"><strong id="heatmap-year-label">${e(financeHeatmapYear)} activity</strong><div class="actions"><button type="button" id="heatmap-year-prev" aria-label="Previous activity year">← Previous year</button><button type="button" id="heatmap-current-year">Current year</button><button type="button" id="heatmap-year-next" aria-label="Next activity year">Next year →</button></div></header><div class="heatmap-scroll"><div class="financial-heatmap" role="group" aria-label="Club activity by day in ${e(financeHeatmapYear)}">${Array.from({length},(_,i)=>{const key=new Date(begin.getTime()+i*86400000).toISOString().slice(0,10),count=Number(lookup.get(key)?.count)||0,level=count===0?0:Math.min(4,Math.ceil(Math.log2(count+1)));return `<button type="button" data-finance-day="${key}" class="heat-cell heat-${level}" tabindex="${i===0?0:-1}" title="${e(humanDate(key))}: ${count} club actions or scheduled proposals" aria-label="${e(humanDate(key))}, ${count} club actions or scheduled proposals">${count?'<span class="sr-only">'+count+'</span>':''}</button>`;}).join('')}</div></div><div class="heatmap-key"><small>Less activity</small>${[0,1,2,3,4].map(level=>`<span class="heat-cell heat-${level}" aria-hidden="true"></span>`).join('')}<small>More activity</small></div>`;}
function wireFinanceHeatmap(target,days){const changeYear=next=>{financeHeatmapYear=next;financeDay=null;target.querySelector('#finance-heatmap').innerHTML=financeHeatmap(days);target.querySelector('#finance-day-history').textContent='Select a day to inspect its activity.';wireFinanceHeatmap(target,days);target.querySelector('#heatmap-year-label').tabIndex=-1;target.querySelector('#heatmap-year-label').focus();};target.querySelector('#heatmap-year-prev').onclick=()=>changeYear(financeHeatmapYear-1);target.querySelector('#heatmap-year-next').onclick=()=>changeYear(financeHeatmapYear+1);target.querySelector('#heatmap-current-year').onclick=()=>changeYear(Number(mytParts(state.server_time||new Date().toISOString()).year));const cells=Array.from(target.querySelectorAll('[data-finance-day]'));cells.forEach((button,index)=>{button.onclick=()=>{financeDay=button.dataset.financeDay;cells.forEach(cell=>cell.setAttribute('aria-pressed',String(cell===button)));const day=days.find(day=>day.date===financeDay),actions=day?.actions||[];target.querySelector('#finance-day-history').innerHTML=`<h3>${e(humanDate(financeDay))} · ${e(day?.count||0)} recorded actions / scheduled proposals</h3>${(day?.event_ids||[]).length?`<div class="info">${day.event_ids.map(id=>`<p>Scheduled event: ${e(financeData.events.find(event=>event.proposal_id===id)?.title||'Event')} · ${e(statusLabel(day.event_statuses?.[id]||financeData.events.find(event=>event.proposal_id===id)?.status))}</p>`).join('')}</div>`:''}${actions.length?`<ol class="activity-timeline">${actions.map(entry=>`<li><strong>${e(humanAction(entry.action))}</strong><small>${e(entry.actor_name||'Recorded user')} · ${e(localTime(entry.timestamp))}</small></li>`).join('')}</ol>`:'<p class="muted">No recorded club actions on this day.</p>'}`;};button.onkeydown=event=>{const offset={ArrowDown:1,ArrowUp:-1,ArrowRight:7,ArrowLeft:-7,Home:-index,End:cells.length-index-1}[event.key];if(offset===undefined)return;event.preventDefault();const next=Math.min(cells.length-1,Math.max(0,index+offset));cells.forEach(cell=>cell.tabIndex=-1);cells[next].tabIndex=0;cells[next].focus();};});}
function financeLedger(entries){return entries.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th scope="col">Recorded</th><th scope="col">Event / description</th><th scope="col">Type</th><th scope="col">Amount</th></tr></thead><tbody>${entries.map(row=>`<tr><td>${e(localTime(row.approved_at||row.created_at||row.posted_at||row.timestamp))}</td><td>${e(row.description||row.title||'Approved actual transaction')}</td><td>${e(humanAction(row.kind||row.type))}</td><td>${money(row.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No approved actual transactions yet.</p>';}
async function loadEventFinance(main,id){const request=++financeRevisionRequest;if(!main.querySelector('#financial-report-form'))main.innerHTML='<p aria-live="polite">Loading event financial report…</p>';const data=await api(`/api/proposals/${id}/finance`);if(request!==financeRevisionRequest||view!=='finance'||!main.isConnected)return;financeInfo=data;if(!financeDraft||financeDraft.proposal_id!==id){financeDraft=structuredClone(data.report||{proposal_id:id,rows:[],variance_reason:''});financeEditVersion=financeSavedVersion=0;financeRemote=null;financeSaveError=financeUploadError='';dirty=false;}else{if(data.report&&financeDraft.revision!==data.report.revision)financeRemote=data.report;for(const key of ['status','history','created_at','updated_at'])if(data.report&&key in data.report)financeDraft[key]=data.report[key];}financialReportForm(main);if(financeRemote)showFinancialRemoteChange();}

function showFinancialRemoteChange(){const main=document.querySelector('#main');if(!main||!financeRemote||main.querySelector('#finance-remote-change'))return;const banner=document.createElement('section');banner.id='finance-remote-change';banner.className='info';banner.setAttribute('role','status');banner.innerHTML='<p>This actual report changed on the server. Your current entries are retained. Load the latest saved report before editing or submitting.</p><button type="button">Load latest saved report</button>';main.prepend(banner);banner.querySelector('button').onclick=()=>{if(dirty&&!confirm('Discard your unsaved actual report entries and load the latest saved report?'))return;financeDraft=structuredClone(financeRemote);financeRemote=null;financeEditVersion=financeSavedVersion=0;dirty=false;clearRecovery();financialReportForm(main);};}
function financialReportCanEdit(){return Boolean(financeInfo?.can_prepare&&['draft','returned'].includes(financeDraft?.status||'draft'));}
function reportTotals(){const rows=financeDraft?.rows||[];return {income:rows.filter(row=>row.kind==='income').reduce((sum,row)=>sum+(Number(row.amount)||0),0),expenses:rows.filter(row=>row.kind==='expense').reduce((sum,row)=>sum+(Number(row.amount)||0),0)};}
function financialReportForm(main){const report=financeDraft,data=financeInfo,editable=financialReportCanEdit(),proposal=state.proposals.find(p=>p.id===report.proposal_id),totals=reportTotals();main.innerHTML=`<header class="pagehead"><div><button type="button" class="link" id="back-finances">← Financial records</button><div class="eyebrow mt16">Actual event financial report</div><h1>${e(data.title)}</h1><p>Record what was received and spent, and attach evidence to each transaction. Submit the actual report after the scheduled event has ended.</p></div><div class="actions">${badge(report.status||'draft')}<button type="button" id="refresh-financial-report">Check saved version</button>${report.id?'<button type="button" id="export-financial-report">Export report PDF</button>':''}</div></header><section class="record-dates"><div><small>Created on server</small><strong>${report.created_at?e(localTime(report.created_at)):'Not saved yet'}</strong></div><div><small>Last saved on server</small><strong>${report.updated_at?e(localTime(report.updated_at)):'Not saved yet'}</strong></div><div><small>Submitted on server</small><strong>${report.submitted_at?e(localTime(report.submitted_at)):'Not submitted'}</strong></div></section><div class="info">Planned: ${money(data.planned_income)} income / ${money(data.planned_expenses)} expenses. Only SLD approval of this actual report changes the club balance.</div><section class="profile-section"><p class="help" id="finance-photo-state">Checking event photo requirements…</p><button type="button" data-event-completion="${e(report.proposal_id)}">Open event completion & photographs</button></section>${returnedRecordMarkup(report,'finance')}${report.history?.length?`<section class="panel"><h2>Review history</h2>${report.history.map(entry=>`<article class="audit"><strong>${e(humanAction(entry.action))}</strong><p>${e(entry.comment||'')}</p><small>${e(entry.name||entry.actor)} · ${e(localTime(entry.timestamp))}</small></article>`).join('')}</section>`:''}<form id="financial-report-form"><section class="panel"><h2>Actual transactions</h2><fieldset class="plain-fieldset" ${editable?'':'disabled'}>${(report.rows||[]).map((row,index)=>financialTransactionRow(row,index,proposal)).join('')||'<p class="muted">No actual transactions entered yet.</p>'}${editable?'<button type="button" id="add-actual-row">+ Add transaction</button>':''}<div id="actual-report-totals" class="totals">${financialTotalsMarkup(totals,data)}</div><div class="fields mt24">${textfield('Variance explanation','variance_reason',report.variance_reason||'','placeholder="Explain differences between the actual figures and the planned budget"')}</div></fieldset></section><section class="panel"><h2>Receipts & supporting files</h2><p class="help">Receipts uploaded beside each item are attached automatically. Downloads require your university session.</p><div class="receipt-list mt20">${(data.receipts||[]).map(receipt=>`<article class="receipt-row"><div><strong>${e(receipt.filename)}</strong><small class="block">${e(localTime(receipt.uploaded_at))} · ${Math.ceil(receipt.size/1024)} KB</small></div><button type="button" data-receipt-download="${e(receipt.id)}">Download</button></article>`).join('')||'<p class="muted">No evidence uploaded for this event.</p>'}</div></section>${editable?'<footer class="formfooter"><small id="financial-save-state" role="status">Changes save automatically.</small><div class="actions"><button type="button" id="retry-financial-save" hidden>Retry save</button><button type="button" class="primary" id="submit-financial-report">Submit to SLD</button></div></footer>':'<p class="help">This submitted or approved actual report is read-only.</p>'}</form>${data.can_review&&report.status==='pending_sld'?`<section class="panel"><h2>SLD financial review</h2><p class="help">Approval posts the actual transactions to the club ledger once. This review records your name and server timestamp.</p><form id="financial-review-form"><div class="fields">${signerIdentityMarkup(data.reviewer_profile).replace('after signing','after approval')}${textfield('Review comment / return reason','comment','')}</div><div class="actions mt20"><button class="primary" type="submit">Approve actual report</button><button type="button" id="return-financial-report">Return for correction</button></div></form></section>`:''}`;main.querySelector('#refresh-financial-report').onclick=()=>action(async()=>{captureFinancialReport();await loadEventFinance(main,report.proposal_id);});main.querySelector('#back-finances').onclick=()=>action(async()=>{await flushFinancialReport();financeDraft=null;financeEventId=null;dirty=false;render({resetScroll:true,preserveFocus:false});});wireItemReceiptUploads(main,report);wireCompletionButtons(main);loadFinancePhotoState(main,report.proposal_id).catch(showRequestError);main.querySelector('#retry-financial-save')?.addEventListener('click',()=>action(saveFinancialReport));const form=main.querySelector('#financial-report-form');form.oninput=()=>{if(!financialReportCanEdit())return;captureFinancialReport();markFinancialChanged();main.querySelector('#actual-report-totals').innerHTML=financialTotalsMarkup(reportTotals(),data);};if(editable){form.onsubmit=event=>{event.preventDefault();action(async()=>{await saveFinancialReport();notice('Actual financial report saved.');});};main.querySelector('#add-actual-row').onclick=()=>{captureFinancialReport();if(financeUploadPromise){notice('Wait for the receipt upload to finish.',true);return;}report.rows.push({kind:'expense',description:'',amount:'',budget_ref:'unplanned',evidence_ids:[]});markFinancialChanged();const position=captureUiPosition();financialReportForm(main);restoreUiPosition(position);};main.querySelectorAll('[data-remove-actual-row]').forEach(button=>button.onclick=()=>{captureFinancialReport();if(financeUploadPromise){notice('Wait for the receipt upload to finish.',true);return;}report.rows.splice(Number(button.dataset.removeActualRow),1);markFinancialChanged();const position=captureUiPosition();financialReportForm(main);restoreUiPosition(position);});main.querySelectorAll('[data-actual-kind]').forEach(input=>input.onchange=()=>{captureFinancialReport();report.rows[Number(input.dataset.actualKind)].budget_ref='unplanned';markFinancialChanged();const position=captureUiPosition();financialReportForm(main);restoreUiPosition(position);});main.querySelector('#submit-financial-report').onclick=()=>action(async()=>{await flushFinancialReport();if(!await confirmSldSubmission({title:data.title,description:'Send the actual transactions and their attached evidence to SLD for review.'}))return;const result=await api(`/api/finance/reports/${financeDraft.id}/submit`,{confirm_submission:true,revision:financeDraft.revision});financeDraft=result.report;dirty=false;await loadEventFinance(main,report.proposal_id);notice('Actual report submitted to SLD.');});}main.querySelectorAll('[data-receipt-download]').forEach(button=>button.onclick=()=>action(()=>downloadFile('/api/receipts/'+button.dataset.receiptDownload,'Evidence')));main.querySelector('#export-financial-report')?.addEventListener('click',()=>action(async()=>{await flushFinancialReport();await downloadFile(`/api/finance/reports/${financeDraft.id}/export/pdf`,'Actual financial report.pdf');}));const review=main.querySelector('#financial-review-form');if(review){const send=async actionName=>{const values=Object.fromEntries(new FormData(review));if(actionName==='return'&&!values.comment.trim())throw Error('Give a reason for returning this report.');const result=await api(`/api/finance/reports/${report.id}/review`,{...values,revision:report.revision,action:actionName});financeDraft=result.report;dirty=false;await loadEventFinance(main,report.proposal_id);notice(actionName==='approve'?'Actual report approved and transactions posted to the ledger.':'Actual report returned for correction.');};review.onsubmit=event=>{event.preventDefault();action(()=>send('approve'));};main.querySelector('#return-financial-report').onclick=()=>action(()=>send('return'));}}
function financialTransactionRow(row,index,proposal){const budgetRows=row.kind==='income'?proposal?.revenue||[]:proposal?.expenses||[],prefix=row.kind==='income'?'revenue':'expenses';return `<section class="actual-transaction"><header class="section-heading"><h3>Transaction ${index+1}</h3><button type="button" data-remove-actual-row="${index}" class="danger">Remove</button></header><div class="fields"><div class="field"><label for="actual_${index}_kind">Transaction type</label><select name="actual_${index}_kind" id="actual_${index}_kind" data-actual-kind="${index}">${['income','expense'].map(kind=>`<option value="${kind}" ${kind===row.kind?'selected':''}>${humanAction(kind)}</option>`).join('')}</select></div>${field('Actual amount (RM) *',`actual_${index}_amount`,row.amount,'number','min="0.01" step="0.01"')}${field('Description *',`actual_${index}_description`,row.description)}<div class="field"><label for="actual_${index}_budget_ref">Planned budget reference</label><select name="actual_${index}_budget_ref" id="actual_${index}_budget_ref"><option value="unplanned">Unplanned transaction</option>${budgetRows.map((budget,i)=>`<option value="${prefix}:${i}" ${row.budget_ref===prefix+':'+i?'selected':''}>${e(budget.description||'Budget item '+(i+1))}</option>`).join('')}</select></div><div class="field full"><label for="item-receipt-${index}">Receipt for this item *</label><input id="item-receipt-${index}" data-item-receipt="${index}" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"><small>PDF or image, up to 2 MB. Attached to this item automatically.</small><small data-item-upload-status="${index}" role="status"></small></div><details class="field full"><summary>Use an uploaded receipt</summary><fieldset class="checkgroup" data-evidence-row="${index}"><legend class="sr-only">Evidence for this item</legend>${(financeInfo.receipts||[]).map(receipt=>`<label class="checkoption"><input type="checkbox" name="actual_${index}_evidence" value="${e(receipt.id)}" ${(row.evidence_ids||[]).includes(receipt.id)?'checked':''}>${e(receipt.filename)}</label>`).join('')||'<small>No uploaded receipts yet.</small>'}</fieldset></details></div></section>`;}
// ITEM_RECEIPTS_START
function wireItemReceiptUploads(main,report){main.querySelectorAll('[data-item-receipt]').forEach(input=>input.onchange=event=>action(async()=>{const file=event.target.files[0];if(!file)return;await uploadItemReceipt(file,report,report.rows[Number(input.dataset.itemReceipt)],main,input);}));main.querySelectorAll('[data-clear-upload-error]').forEach(button=>button.onclick=()=>{financeUploadError='';updateFinanceSaveStatus();button.remove();});}
async function uploadItemReceipt(file,report,row,main,input){if(financeUploadPromise)throw Error('Wait for the current receipt upload to finish.');if(file.size>2*1024*1024||!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PDF, PNG, JPEG or WebP receipt no larger than 2 MB.');captureFinancialReport();financeUploadError='';const controls=Array.from(main.querySelectorAll('[data-actual-kind],[data-remove-actual-row],#add-actual-row')).map(button=>({button,disabled:button.disabled}));controls.forEach(({button})=>button.disabled=true);const info=financeInfo;financeUploadPromise=(async()=>{const content=await readReceipt(file),result=await api('/api/receipts',{proposal_id:report.proposal_id,filename:file.name,mime:file.type,content_base64:content});if(financeDraft!==report||view!=='finance'||!report.rows.includes(row))throw Error('This receipt belongs to the previous item. Reopen its event to attach the uploaded file.');info.receipts.push(result.receipt);row.evidence_ids??=[];if(!row.evidence_ids.includes(result.receipt.id))row.evidence_ids.push(result.receipt.id);const index=report.rows.indexOf(row),status=main.querySelector(`[data-item-upload-status="${index}"]`);if(status)status.textContent='Attached: '+result.receipt.filename;const checks=main.querySelector(`[data-evidence-row="${index}"]`);if(checks)checks.insertAdjacentHTML('beforeend',`<label class="checkoption"><input type="checkbox" name="actual_${index}_evidence" value="${e(result.receipt.id)}" checked>${e(result.receipt.filename)}</label>`);markFinancialChanged();await saveFinancialReport();})();updateFinanceSaveStatus();try{await financeUploadPromise;}catch(error){financeUploadError=error.message;const status=input?.parentElement?.querySelector('[data-item-upload-status]');if(status){status.textContent=error.message;if(!status.parentElement.querySelector('[data-clear-upload-error]')){const button=document.createElement('button');button.type='button';button.textContent='Clear failed upload';button.dataset.clearUploadError='';button.onclick=()=>{financeUploadError='';input.value='';button.remove();updateFinanceSaveStatus();};status.after(button);}}throw error;}finally{financeUploadPromise=null;controls.forEach(({button,disabled})=>{if(button.isConnected)button.disabled=disabled;});updateFinanceSaveStatus();}}
// ITEM_RECEIPTS_END
function financialTotalsMarkup(totals,data){return `<div><small>Actual income</small><strong>${money(totals.income)}</strong></div><div><small>Actual expenses</small><strong>${money(totals.expenses)}</strong></div><div><small>Actual net</small><strong>${money(totals.income-totals.expenses)}</strong></div><div><small>Variance from planned net</small><strong>${money((totals.income-totals.expenses)-(Number(data.planned_income)-Number(data.planned_expenses)))}</strong></div>`;}
function captureFinancialReport(){if(!financialReportCanEdit())return;const form=document.querySelector('#financial-report-form');if(!form)return;for(const element of Array.from(form.elements)){const match=element.name?.match(/^actual_(\d+)_(kind|description|amount|budget_ref)$/);if(match)financeDraft.rows[Number(match[1])][match[2]]=element.value;}financeDraft.rows.forEach((row,index)=>row.evidence_ids=Array.from(form.querySelectorAll(`[name=actual_${index}_evidence]`)).filter(input=>input.checked).map(input=>input.value));financeDraft.variance_reason=form.elements.variance_reason.value;}
function updateFinanceSaveStatus(){const status=document.querySelector('#financial-save-state');if(status)status.textContent=financeUploadPromise?'Uploading receipt…':financeUploadError?'Receipt not saved: '+financeUploadError:financeSaveError?'Not saved: '+financeSaveError:financeSavePromise?'Saving actual report…':financeEditVersion>financeSavedVersion?'Changes waiting to save…':'All changes saved';const retry=document.querySelector('#retry-financial-save');if(retry)retry.hidden=!financeSaveError;}
function markFinancialChanged(){dirty=true;financeEditVersion++;financeSaveError='';if(sessionExpired)persistRecovery();updateFinanceSaveStatus();clearTimeout(financeSaveTimer);financeSaveTimer=setTimeout(()=>saveFinancialReport().catch(error=>notice(error.message,true)),700);}
async function saveFinancialReport(){if(typeof financeSaveTimer!=='undefined')clearTimeout(financeSaveTimer);if(!financialReportCanEdit())return;captureFinancialReport();if(financeRemote)throw Error('A newer actual report exists. Load its saved version before continuing; your entries are retained.');if(financeSavePromise)return financeSavePromise;const draft=financeDraft;financeSavePromise=(async()=>{while(financeDraft===draft&&(financeEditVersion>financeSavedVersion||!draft.id)){const version=financeEditVersion,result=await api('/api/finance/reports',{report:financeRecovery(draft)});if(financeDraft!==draft)return;for(const [key,value] of Object.entries(result.report))if(!['rows','variance_reason'].includes(key))draft[key]=value;financeSavedVersion=version;dirty=financeEditVersion>financeSavedVersion;}financeSaveError='';if(!dirty)clearRecovery();})();if(typeof updateFinanceSaveStatus==='function')updateFinanceSaveStatus();try{await financeSavePromise;}catch(error){dirty=true;financeSaveError=error.message;if(error.status===409){try{const fresh=await api(`/api/proposals/${draft.proposal_id}/finance`);if(financeDraft===draft&&fresh.report){financeInfo=fresh;financeRemote=fresh.report;showFinancialRemoteChange();}}catch{/* Local entries remain when the version check is unavailable. */}}throw error;}finally{financeSavePromise=null;if(typeof updateFinanceSaveStatus==='function')updateFinanceSaveStatus();}}
async function flushFinancialReport(){if(!financeDraft)return;if(typeof financeUploadPromise!=='undefined'&&financeUploadPromise)await financeUploadPromise;if(typeof financeUploadError!=='undefined'&&financeUploadError)throw Error('The receipt upload failed. Retry or clear the failed upload before leaving.');if(dirty||(!financeDraft.id&&financialReportCanEdit())){if(!financialReportCanEdit())throw Error('Your actual report changes are not saved. Stay here and check your access.');await saveFinancialReport();}}
function readReceipt(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('The evidence file could not be read. Select it again.'));reader.readAsDataURL(file);});}

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&financeDraft&&dirty)persistRecovery();});
window.addEventListener('pagehide',()=>{if(financeDraft&&dirty)persistRecovery();});

function plannedDuration(p){const date=p.date,endDate=p.end_date||date,validDate=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const parsed=new Date(value+'T00:00:00Z');return Number.isFinite(parsed.getTime())&&parsed.toISOString().slice(0,10)===value;},validTime=value=>{const match=String(value||'').match(/^(\d{2}):(\d{2})(?::(\d{2}))?$/);return Boolean(match&&Number(match[1])<24&&Number(match[2])<60&&Number(match[3]||0)<60);};if(!validDate(date)||!validDate(endDate)||!validTime(p.start_time)||!validTime(p.end_time))return {seconds:null,label:''};const start=new Date(date+'T'+p.start_time+'+08:00'),end=new Date(endDate+'T'+p.end_time+'+08:00'),seconds=(end-start)/1000;if(!Number.isFinite(seconds)||seconds<=0)return {seconds:null,label:''};let remainder=seconds;const units=[[86400,'day'],[3600,'hour'],[60,'minute'],[1,'second']],labels=[];for(const [size,name] of units){const value=Math.floor(remainder/size);remainder%=size;if(value)labels.push(value+' '+name+(value===1?'':'s'));}return {seconds,label:labels.join(' ')};}
function durationField(p){const duration=plannedDuration(p);return `<div class="field"><label for="derived-duration">Calculated duration</label><input id="derived-duration" readonly value="${e(duration.label||p.duration||'Enter the start and end schedule')}" aria-describedby="duration-help"><small id="duration-help">Calculated from the event schedule in Malaysia time. The server confirms the saved duration.</small></div>`;}
function updateDerivedDuration(){const input=document.querySelector('#derived-duration');if(input&&proposalDraft)input.value=plannedDuration(proposalDraft).label||'Enter a valid start and end schedule';}
function collaborationEditor(p){const ids=p.collaboration_club_ids||[],other=Boolean(p.collaboration_other_enabled),catalog=state.collaboration_clubs||[];return `<details class="optional-details full"><summary>Optional collaboration · ${ids.length+(other?1:0)} partners</summary><fieldset class="field full collaboration-picker checkgroup"><legend>Collaboration (optional)</legend><p class="help full">Select registered clubs, or specify another partner. Collaboration does not grant access to your proposal.</p><label class="checkoption"><input type="checkbox" id="collaboration-none" ${!ids.length&&!other?'checked':''}>None</label>${catalog.filter(club=>club.id!==p.club_id).map(club=>`<label class="checkoption"><input type="checkbox" name="collaboration_club_ids" value="${e(club.id)}" ${ids.includes(club.id)?'checked':''}>${e(club.name)}</label>`).join('')}<label class="checkoption"><input type="checkbox" name="collaboration_other_enabled" id="collaboration-other-toggle" ${other?'checked':''}>Other partner</label><div class="conditional-field full" id="collaboration-other-fields" ${other?'':'hidden'}>${field('Other collaboration *','collaboration_other',p.collaboration_other||'','text',other?'required':'disabled')}</div></fieldset></details>`;}
// PROPOSAL_VALIDATION_START — pure rules shared by wizard regression checks.
function proposalStepErrors(p){const errors={0:{},1:{},2:{}},has=value=>typeof value==='string'&&Boolean(value.trim());for(const [key,label] of [['title','Event title'],['summary','Event summary'],['venue',p.mode==='Virtual'?'Online platform / joining location':'Venue'],['introduction','Introduction'],['eligibility','Target audience']])if(!has(p[key]))errors[0][key]='Enter '+label.toLowerCase()+'.';const objectives=Array.isArray(p.objectives)?p.objectives:String(p.objectives||'').split(/\r?\n/);if(objectives.length<2||objectives.some(value=>!has(value))||new Set(objectives.map(value=>String(value).trim().toLowerCase())).size!==objectives.length)errors[0].objectives='Enter at least two different, completed objectives.';for(const [key,label] of [['date','event start date'],['start_time','start time'],['end_time','end time']])if(!has(p[key]))errors[0][key]='Enter the '+label+'.';if(p.date&&p.start_time&&p.end_time&&plannedDuration(p).seconds===null)errors[0].end_time='The event end must be after the start. Check both dates and times.';if(!/^\d+$/.test(String(p.target_count||''))||Number(p.target_count)<=0)errors[0].target_count='Enter a positive whole number of expected participants.';if((p.nature||[]).includes('Others')&&!has(p.nature_other))errors[0].nature_other='Describe the other event nature.';if(p.collaboration_other_enabled&&!has(p.collaboration_other))errors[0].collaboration_other='Name the other collaboration partner.';for(const [key,labels] of [['activities',['name','description']],['itinerary',['start','end','agenda']],['committee',['email','name','role','responsibility']]]){const rows=p[key]||[];if(!rows.length)errors[1][key]='Add at least one '+(key==='activities'?'activity':key==='itinerary'?'itinerary item':'event committee member')+'.';rows.forEach((row,index)=>labels.forEach(field=>{if(!has(row[field]))errors[1][key+'_'+index+'_'+field]='Complete '+field+' for '+(key==='committee'?'committee member':key==='activities'?'activity':'itinerary item')+' '+(index+1)+'.';}));}for(const key of ['ict','logistics'])if((key==='ict'||p.mode!=='Virtual')&&(p[key+'_required']??true)&&!has(p[key]))errors[1][key]='Describe the requested '+(key==='ict'?'ICT':'logistics')+' support, or uncheck it if not needed.';if(!has(p.conclusion))errors[2].conclusion='Enter the proposal conclusion.';for(const key of ['revenue','expenses'])(p[key]||[]).forEach((row,index)=>{if(!has(row.description))errors[2][key+'_'+index+'_description']='Describe budget item '+(index+1)+'.';if(String(row.price??'').trim()===''||!Number.isFinite(Number(row.price))||Number(row.price)<0)errors[2][key+'_'+index+'_price']='Enter a nonnegative unit price for budget item '+(index+1)+'.';if(String(row.quantity??'').trim()===''||!Number.isFinite(Number(row.quantity))||Number(row.quantity)<=0)errors[2][key+'_'+index+'_quantity']='Enter a positive quantity for budget item '+(index+1)+'.';});return errors;}
function firstProposalErrorStep(errors,throughStep){for(let step=0;step<=throughStep;step++)if(Object.keys(errors[step]||{}).length)return step;return null;}
// PROPOSAL_VALIDATION_END
function proposalErrorTarget(form,key){if(key==='objectives')return form.querySelector('[name=objective_0]');return Array.from(form.elements).find(input=>input.name===key)||form.querySelector(`[data-add-row="${key}"]`);}
function clearProposalFieldError(input){if(!input?.name)return;input.removeAttribute('aria-invalid');const note=document.querySelector('#error-'+input.name);note?.remove();input.removeAttribute('aria-describedby');}
function showProposalValidation(errors){const form=document.querySelector('#proposalform');if(!form)return;form.querySelector('#proposal-validation-summary')?.remove();form.querySelectorAll('.wizard-field-error').forEach(note=>note.remove());form.querySelectorAll('[aria-invalid=true]').forEach(input=>input.removeAttribute('aria-invalid'));const summary=document.createElement('section');summary.id='proposal-validation-summary';summary.className='inline-error validation-summary';summary.tabIndex=-1;summary.setAttribute('role','alert');summary.innerHTML='<h2>Complete this section before continuing</h2><ul></ul>';form.prepend(summary);let first=null;for(const [key,message] of Object.entries(errors)){const target=proposalErrorTarget(form,key),item=document.createElement('li');if(target){if(!target.id)target.id='wizard-'+key;target.setAttribute('aria-invalid','true');const note=document.createElement('small');note.id='error-'+(target.name||key);note.className='field-error wizard-field-error';note.textContent=message;target.setAttribute('aria-describedby',note.id);target.insertAdjacentElement('afterend',note);const link=document.createElement('a');link.href='#'+target.id;link.textContent=message;link.onclick=event=>{event.preventDefault();target.focus();};item.append(link);first??=target;}else item.textContent=message;summary.querySelector('ul').append(item);}summary.focus();if(first)setTimeout(()=>first.focus(),0);}
function applyWizardRequiredMarkers(form,p){const step=proposalStep,requiredNames=step===0?['club_id','title','summary','date','start_time','end_time','venue','target_count','introduction','eligibility','mode']:step===2?['conclusion']:[];for(const input of Array.from(form.elements)){if(!input.name||input.disabled||input.type==='checkbox')continue;const required=requiredNames.includes(input.name)||/^objective_\d+$/.test(input.name)||/^(activities|itinerary)_\d+_(name|description|start|end|agenda)$/.test(input.name)||/^committee_\d+_(email|name|role|responsibility)$/.test(input.name)||/^(revenue|expenses)_\d+_(description|price|quantity)$/.test(input.name)||input.name==='nature_other'&&(p.nature||[]).includes('Others')||input.name==='collaboration_other'&&p.collaboration_other_enabled||['ict','logistics'].includes(input.name)&&(input.name==='ict'||p.mode!=='Virtual')&&(p[input.name+'_required']??true);input.required=Boolean(required);if(input.name==='target_count')input.min='1';const label=form.querySelector(`label[for="${input.id}"]`);if(label&&required&&!label.querySelector('.required-star'))label.innerHTML=requiredLabel(label.textContent.replace(/\s*\*$/,'')+' *');}}
function syncProposalConditionalFields(){const form=document.querySelector('#proposalform'),p=proposalDraft;if(!form||!p)return;const nature=form.querySelector('#nature-other-fields');if(nature){nature.hidden=!(p.nature||[]).includes('Others');const input= nature.querySelector('input');input.disabled=nature.hidden;input.required=!nature.hidden;}const other=form.querySelector('#collaboration-other-fields');if(other){other.hidden=!p.collaboration_other_enabled;const input=other.querySelector('input');input.disabled=other.hidden;input.required=!other.hidden;}const none=form.querySelector('#collaboration-none');if(none)none.checked=!(p.collaboration_club_ids||[]).length&&!p.collaboration_other_enabled;for(const key of ['ict','logistics']){const wrapper=form.querySelector(`[data-support="${key}"]`),toggle=form.elements[key+'_required'];if(!wrapper||!toggle)continue;const inapplicable=key==='logistics'&&p.mode==='Virtual';wrapper.hidden=inapplicable;toggle.disabled=inapplicable||!proposalCanEdit(p);if(inapplicable)toggle.checked=false;const area=form.querySelector(`[data-support-fields="${key}"]`);area.hidden=!toggle.checked;const input=form.elements[key];input.disabled=!toggle.checked||inapplicable||!proposalCanEdit(p);input.required=toggle.checked&&!inapplicable;const note=form.querySelector(`[data-support-note="${key}"]`);if(note)note.textContent=toggle.checked?'Describe the support needed for this event.':'Not applicable — no support requested.';}const transport=form.querySelector('#logistics-travel-fields');if(transport){transport.hidden=p.mode==='Virtual'||!p.logistics_required;transport.querySelectorAll('input,textarea').forEach(input=>input.disabled=transport.hidden||!proposalCanEdit(p));}const environment=form.elements.environment;if(environment){environment.disabled=p.mode==='Virtual'||!proposalCanEdit(p);environment.closest('.field').hidden=p.mode==='Virtual';}const indemnity=document.querySelector('#outdoor-indemnity');if(indemnity)indemnity.hidden=p.mode==='Virtual'||p.environment!=='Outdoor';const collaboration=form.querySelector('.collaboration-picker')?.closest('details');if(collaboration)collaboration.querySelector('summary').textContent='Optional collaboration · '+((p.collaboration_club_ids||[]).length+(p.collaboration_other_enabled?1:0))+' partners';const sdgs=form.querySelector('#sdgs')?.closest('details');if(sdgs)sdgs.querySelector('summary').textContent='Optional Sustainable Development Goals · '+(p.sdgs||[]).length+' selected';const venue=form.querySelector('label[for=venue]');if(venue)venue.innerHTML=requiredLabel((p.mode==='Virtual'?'Online platform / joining location':'Venue')+' *');applyWizardRequiredMarkers(form,p);}
function wireWizard(main,p){const form=main.querySelector('#proposalform');form.noValidate=true;const none=form.querySelector('#collaboration-none');if(none)none.onchange=()=>{if(none.checked){form.querySelectorAll('[name=collaboration_club_ids],[name=collaboration_other_enabled]').forEach(input=>input.checked=false);captureProposal();markProposalChanged();syncProposalConditionalFields();}};syncProposalConditionalFields();updateDerivedDuration();}

function activitySummaryMarkup(summary){if(!summary)return '<p class="help">Recorded activity summary is unavailable.</p>';const count=records=>Object.values(records||{}).reduce((sum,value)=>sum+(Number(value)||0),0),proposal=summary.proposal_statuses||{},reports=summary.finance_report_statuses||{};return `<details class="activity-breakdown"><summary>${e(summary.logged_actions||0)} recorded actions · ${e(count(proposal))} proposals · ${e(count(reports))} actual reports</summary><div class="activity-summary-columns"><section><h3>Proposal states</h3><dl>${Object.entries(proposal).map(([status,value])=>`<div><dt>${e(statusLabel(status))}</dt><dd>${e(value)}</dd></div>`).join('')||'<div><dt>No proposals</dt><dd>0</dd></div>'}</dl></section><section><h3>Actual report states</h3><dl>${Object.entries(reports).map(([status,value])=>`<div><dt>${e(statusLabel(status))}</dt><dd>${e(value)}</dd></div>`).join('')||'<div><dt>No actual reports</dt><dd>0</dd></div>'}</dl></section><section><h3>Recorded actions</h3><dl>${Object.entries(summary.by_action||{}).map(([action,value])=>`<div><dt>${e(humanAction(action))}</dt><dd>${e(value)}</dd></div>`).join('')||'<div><dt>No recorded actions</dt><dd>0</dd></div>'}</dl></section></div><p class="help">Activity counts include every recorded workflow stage. Financial balances include only the opening balance and SLD-approved actual reports.</p></details>`;}

// WORKSPACE_SCROLL_START — one document scroll; preserve row/editor position.
function captureUiPosition(){const active=document.activeElement,form=document.querySelector('form');return {x:typeof window==='undefined'?0:window.scrollX,y:typeof window==='undefined'?0:window.scrollY,id:active?.id,name:active?.name,tag:active?.tagName,dataset:active?.dataset?JSON.stringify(active.dataset):'',start:active?.selectionStart,end:active?.selectionEnd,details:form?Array.from(form.querySelectorAll('details')).map(detail=>detail.open):[]};}
function restoreUiPosition(position,options={}){const form=document.querySelector('form');if(form&&!options.resetScroll)form.querySelectorAll('details').forEach((detail,index)=>{if(index<position.details.length)detail.open=position.details[index];});if(options.preserveFocus!==false&&!options.resetScroll){const nodes=Array.from(document.querySelectorAll('input,textarea,select,button,a,[tabindex]'));const active=position.id?nodes.find(node=>node.id===position.id):position.name?nodes.find(node=>node.name===position.name):position.dataset&&position.dataset!=='{}'?nodes.find(node=>node.tagName===position.tag&&JSON.stringify(node.dataset)===position.dataset):null;if(active&&!active.disabled){active.focus({preventScroll:true});if(Number.isInteger(position.start)&&typeof active.setSelectionRange==='function')try{active.setSelectionRange(position.start,position.end);}catch{}}}if(typeof window!=='undefined'&&typeof window.scrollTo==='function')window.scrollTo({left:options.resetScroll?0:position.x,top:options.resetScroll?0:position.y,behavior:'instant'});}
// WORKSPACE_SCROLL_END
function wireResponsiveMenu(){if(typeof matchMedia!=='function')return;const query=matchMedia('(max-width:768px)');if(wireResponsiveMenu.bound)return;wireResponsiveMenu.bound=true;query.addEventListener('change',event=>{const menu=document.querySelector('.workspace-menu');if(menu)menu.open=!event.matches;});}
function workspaceKind(){if(state.user.role==='sld')return 'sld';return state.user.role==='advisor'||state.clubs.some(club=>club.advisor_email===state.user.email)?'advisor':'student';}
function workspaceLabel(kind=workspaceKind()){return {sld:'SLD administration',advisor:'Advisor workspace',student:'Student workspace'}[kind];}
function viewTitle(key){return {withdrawals:'Fund withdrawals',withdrawal:'Withdrawal record',completionlist:'Event completion',completion:'Completion record',dashboard:'Overview',reviews:'Review queue',notifications:'Notifications',clubs:'Club registrations & profiles',proposals:'Event proposals',finance:'Financial records',calendar:'Approved event calendar',contacts:'University contacts',browseclubs:'Club directory',studentprofile:'Student profile',agm:'Annual AGM reports',weekly:'Weekly activities',reports:'Weekly activities',performance:'Club performance',assistant:'Student Life assistant',events:'Upcoming events',settings:'Operational settings',profile:'Account profile',activity:'Recorded activity'}[key]||'Student Life';}
function navigationGroups(kind){const finance=state.clubs.length||state.proposals.some(proposal=>proposal.status==='approved'),records=state.clubs.length||state.proposals.length||(state.registration_grants||[]).length?[['clubs',kind==='student'?'My clubs':'Assigned clubs'],['proposals',kind==='student'?'My events':'Event proposals'],...(finance?[['finance','Financial records']]:[])]:[];if(kind==='sld')return [['Operations',[['dashboard','Overview'],['reviews','Review queue'],['notifications','Notifications'],['assistant','Assistant']]],['Club & event records',[['clubs','Club registrations'],['proposals','Event proposals'],['completionlist','Event completion'],['withdrawals','Fund withdrawals'],['agm','AGM reports'],['weekly','Weekly activities'],['performance','Club performance'],...(finance?[['finance','Financial records']]:[]),['calendar','Event calendar'],['browseclubs','Browse clubs']]],['Administration',[['contacts','University contacts'],['activity','Recorded activity'],['settings','Settings'],['profile','My account']]]];return [[kind==='advisor'?'Review workspace':'Workspace',[['dashboard','Overview'],...(kind==='advisor'||(state.club_reports||[]).some(report=>report.can_sign&&!report.can_edit)?[['reviews','Review queue']]:[]),['notifications','Notifications'],['assistant','Assistant'],['events','Upcoming events'],['browseclubs','Browse clubs']]],['Assigned work',[...records,...(records.length?[['completionlist','Event completion'],['withdrawals','Fund withdrawals']]:[]),...(performanceCanView()?[['performance','Club performance']]:[]),...(state.clubs.length||(state.club_reports||[]).length?[['agm','AGM reports'],['weekly','Weekly activities']]:[])]],['Account',[['activity','Recorded activity'],['profile','My account']]]];}
function workspaceNavigation(kind){return navigationGroups(kind).map(([label,items])=>`<section class="nav-group"><h2>${e(label)}</h2>${items.map(([key,title])=>`<button type="button" data-nav="${key}" ${view===key?'aria-current="page"':''}>${icon(key)}<span>${e(title)}</span>${key==='notifications'?notificationBadge():''}</button>`).join('')}</section>`).join('');}
function notificationBadge(){const count=Number(state.notifications_unread_count)||0;return `<span class="notification-count" data-unread-badge ${count?'':'hidden'} aria-label="${count} unread notifications">${count>99?'99+':count}</span>`;}
function updateNotificationBadge(){const count=Number(state.notifications_unread_count)||0;document.querySelectorAll('[data-unread-badge]').forEach(badge=>{badge.hidden=!count;badge.textContent=count>99?'99+':String(count);badge.setAttribute('aria-label',count+' unread notifications');});}
function reviewAssignments(){const isSld=state.user.role==='sld',clubs=visibleClubs().filter(club=>isSld?['pending_sld','reviewing_sld'].includes(club.status):club.status==='pending_advisor'&&club.advisor_email===state.user.email),proposals=visibleProposals().filter(proposal=>isSld?proposal.status==='pending_sld':proposal.status==='pending_advisor'&&proposalClub(proposal)?.advisor_email===state.user.email);return {clubs,proposals};}
function reviewProposalRows(proposals){return proposals.map(proposal=>`<article class="clubrow"><div><h3>${e(proposal.title||'Untitled event proposal')}</h3><p>${e(proposalClub(proposal)?.name||'Organising club')} · ${e(humanDate(proposal.date||'Schedule not entered'))}</p>${badge(proposal.status)}</div><button type="button" data-dashboard-proposal="${e(proposal.id)}">Review proposal</button></article>`).join('')||'<p class="muted">No event proposals awaiting your review.</p>';}
function reviewsPage(){const main=app.querySelector('main'),queue=reviewAssignments();if(workspaceKind()==='student'&&!(state.club_reports||[]).some(report=>report.can_sign&&!report.can_edit)){main.innerHTML='<div class="info">Review actions are available to assigned advisors and SLD.</div>';return;}main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">${e(workspaceLabel())}</div><h1>Review queue</h1><p>${state.user.role==='sld'?'Check advisor-endorsed submissions and actual financial reports.':'Review club registrations and event proposals assigned to you before sending them to SLD.'}</p></div><button type="button" id="refresh-reviews">Refresh queue</button></header><section class="panel"><header class="section-heading"><h2>Club registrations</h2><span class="badge">${queue.clubs.length} awaiting review</span></header><div id="review-registration-items">${queue.clubs.length?queue.clubs.map(clubRow).join(''):'<p class="muted">No registrations awaiting your review.</p>'}</div></section><section class="panel"><header class="section-heading"><h2>Event proposals</h2><span class="badge">${queue.proposals.length} awaiting review</span></header><div id="review-proposal-items">${reviewProposalRows(queue.proposals)}</div></section>${state.user.role==='sld'?'<section class="panel"><h2>Actual financial reports</h2><div id="financial-review-items" aria-live="polite">Loading financial review queue…</div></section>':''}`;main.querySelector('#refresh-reviews').onclick=()=>action(async()=>{await refresh();const position=captureUiPosition();reviewsPage();restoreUiPosition(position);});wireClubOpen(main);wireDashboardProposals(main);if(state.user.role==='sld')loadFinancialReviewQueue(main).catch(showRequestError);}
async function loadFinancialReviewQueue(main){const target=main.querySelector('#financial-review-items'),results=await Promise.allSettled(visibleClubs().map(club=>api('/api/finance?club_id='+encodeURIComponent(club.id))));if(!target?.isConnected)return;const events=results.flatMap(result=>result.status==='fulfilled'?(result.value.events||[]).filter(event=>event.report_status==='pending_sld'):[]);target.innerHTML=events.length?events.map(event=>`<article class="clubrow"><div><h3>${e(event.title)}</h3><p>Actual income ${money(event.actual_income)} · expenses ${money(event.actual_expenses)}</p><span class="badge">SLD financial review</span></div><button type="button" data-finance-event="${e(event.proposal_id)}">Review actual report</button></article>`).join(''):results.some(result=>result.status==='rejected')?'<p class="muted">Some financial queues could not be loaded. Refresh the queue to retry.</p>':'<p class="muted">No actual financial reports awaiting SLD.</p>';wireFinanceEventLinks(target);}
function advisorDashboardPage(){const main=app.querySelector('main'),queue=reviewAssignments();main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">Advisor workspace</div><h1>Assigned reviews</h1><p>Prioritise submissions requiring your endorsement. Club and event responsibilities remain separate.</p></div><button type="button" id="advisor-reviewqueue">Open review queue</button></header><div class="overview-metrics"><div><strong>${queue.clubs.length}</strong><span>Registrations to review</span></div><div><strong>${queue.proposals.length}</strong><span>Proposals to review</span></div><div><strong>${visibleClubs().length}</strong><span>Assigned clubs</span></div></div><section class="panel"><h2>Club registrations awaiting endorsement</h2><div id="advisor-registration-queue">${queue.clubs.length?queue.clubs.map(clubRow).join(''):'<p class="muted">No registrations requiring your endorsement.</p>'}</div></section><section class="panel"><h2>Event proposals awaiting endorsement</h2><div id="advisor-proposal-queue">${reviewProposalRows(queue.proposals)}</div></section><details class="panel assigned-club-disclosure"><summary>Assigned club profiles and registrations</summary><div class="mt20">${visibleClubs().map(clubRow).join('')||'<p class="muted">No club-level assignments.</p>'}</div></details>`;main.querySelector('#advisor-reviewqueue').onclick=()=>navigate('reviews');wireClubOpen(main);wireDashboardProposals(main);}
function updateBackgroundWorkspace(){const position=captureUiPosition();updateReportQueue();if(view==='dashboard'){if(state.user.role==='sld')updateDashboardQueues();else if(workspaceKind()==='advisor'){const queue=reviewAssignments();document.querySelectorAll('.overview-metrics strong').forEach((element,index)=>{element.textContent=[queue.clubs.length,queue.proposals.length,visibleClubs().length][index];});const registrations=document.querySelector('#advisor-registration-queue'),proposals=document.querySelector('#advisor-proposal-queue');if(registrations)registrations.innerHTML=queue.clubs.map(clubRow).join('')||'<p class="muted">No registrations requiring your endorsement.</p>';if(proposals)proposals.innerHTML=reviewProposalRows(queue.proposals);wireClubOpen(document.querySelector('#main'));wireDashboardProposals(document.querySelector('#main'));}else{const counts=[visibleClubs().length,visibleProposals().length,visibleProposals().filter(proposal=>['pending_advisor','pending_sld'].includes(proposal.status)).length,visibleProposals().filter(proposal=>proposal.status==='approved').length];document.querySelectorAll('.stat strong').forEach((element,index)=>{if(index<counts.length)element.textContent=counts[index];});}}else if(view==='reviews'){const queue=reviewAssignments(),registrations=document.querySelector('#review-registration-items'),proposals=document.querySelector('#review-proposal-items');if(registrations)registrations.innerHTML=queue.clubs.map(clubRow).join('')||'<p class="muted">No registrations awaiting your review.</p>';if(proposals)proposals.innerHTML=reviewProposalRows(queue.proposals);wireClubOpen(document.querySelector('#main'));wireDashboardProposals(document.querySelector('#main'));}else if(['agm','weekly'].includes(view)&&!reportDraft){updateReportList(view);if(state.user.role==='sld'){const main=document.querySelector('#main');(view==='agm'?loadAgmTracking(main):loadWeeklyTracking(main)).catch(showRequestError);}}else if(!document.querySelector('form')&&view==='clubs'&&!clubProfile)clubPage();else if(!document.querySelector('form')&&view==='proposals')proposalPage();restoreUiPosition(position);}
let notificationsOffset=0,notificationItems=[],notificationRequest=0;
function notificationsPage(){const main=app.querySelector('main');main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">University workflow</div><h1>Notifications</h1><p>Updates for your current club and event assignments. Draft autosaves do not generate notifications.</p></div><button type="button" id="refresh-notifications">Refresh inbox</button></header><section class="panel inbox-panel"><div id="notification-items" aria-live="polite">Loading notifications…</div><div class="formfooter"><small id="notification-range"></small><div class="actions"><button type="button" id="notification-previous">← Previous</button><button type="button" id="notification-next">Next →</button></div></div></section>`;main.querySelector('#refresh-notifications').onclick=()=>loadNotifications().catch(showRequestError);main.querySelector('#notification-previous').onclick=()=>{notificationsOffset=Math.max(0,notificationsOffset-25);loadNotifications().catch(showRequestError);};main.querySelector('#notification-next').onclick=()=>{notificationsOffset+=25;loadNotifications().catch(showRequestError);};loadNotifications().catch(showRequestError);}
async function loadNotifications(){const position=captureUiPosition(),request=++notificationRequest,data=await api(`/api/notifications?offset=${notificationsOffset}&limit=25`);if(request!==notificationRequest||view!=='notifications')return;notificationItems=data.notifications||[];state.notifications_unread_count=data.unread_count||0;updateNotificationBadge();const target=document.querySelector('#notification-items');target.innerHTML=notificationItems.map(item=>`<article tabindex="-1" data-notification-row="${e(item.id)}" class="notification-row ${item.read_at?'read':'unread'}"><div><div class="notification-state">${item.read_at?'Read':'Unread'} · ${e(localTime(item.created_at))}</div><h2>${e(item.title)}</h2><p>${e(item.message)}</p>${item.club_name?`<small>${e(item.club_name)}</small>`:''}</div><div class="actions">${item.record_type&&item.record_id?`<button type="button" data-notification-open="${e(item.id)}">Open record</button>`:''}${item.read_at?'':`<button type="button" data-notification-read="${e(item.id)}">Mark as read</button>`}</div></article>`).join('')||'<section class="empty"><h2>No notifications</h2><p>Relevant submission, review and assignment updates will appear here.</p></section>';const total=Number(data.total)||0;document.querySelector('#notification-range').textContent=total?`${notificationsOffset+1}–${notificationsOffset+notificationItems.length} of ${total}`:'Inbox is empty';document.querySelector('#notification-previous').disabled=notificationsOffset===0;document.querySelector('#notification-next').disabled=notificationsOffset+notificationItems.length>=total;target.querySelectorAll('[data-notification-read]').forEach(button=>button.onclick=()=>action(async()=>{const id=button.dataset.notificationRead;await markNotificationRead(id);await loadNotifications();document.querySelector(`[data-notification-row="${CSS.escape(id)}"]`)?.focus({preventScroll:true});}));target.querySelectorAll('[data-notification-open]').forEach(button=>button.onclick=()=>action(()=>openNotificationRecord(notificationItems.find(item=>item.id===button.dataset.notificationOpen))));restoreUiPosition(position);}
async function markNotificationRead(id){const result=await api('/api/notifications/'+encodeURIComponent(id)+'/read',{});state.notifications_unread_count=result.unread_count||0;updateNotificationBadge();return result.notification;}
async function openNotificationRecord(item){if(!item)throw Error('This notification is no longer available. Refresh the inbox.');await markNotificationRead(item.id);await leaveCurrent();await refresh();clubDraft=clubProfile=proposalDraft=null;financeDraft=null;financeEventId=null;if(item.record_type==='withdrawal'){await openOperation('withdrawal',item.record_id);return;}if(item.record_type==='event_completion'){if(!item.proposal_id)throw Error('Refresh this notification to open its completion record.');await openOperation('completion',item.proposal_id);return;}if(item.record_type==='proposal'){const proposal=state.proposals.find(proposal=>proposal.id===item.record_id);if(!proposal)throw Error('This event is not available under your current assignment. Refresh the inbox.');resetProposalAutosave();proposalDraft=structuredClone(proposal);proposalStep=0;view='proposals';}else if(item.record_type==='finance_report'){const proposal=state.proposals.find(proposal=>proposal.id===item.proposal_id);if(!proposal)throw Error('This financial report is not available under your current assignment.');financeEventId=proposal.id;view='finance';}else if(item.record_type==='club'){let club=state.clubs.find(club=>club.id===item.record_id);if(!club)throw Error('This registration is not available under your current assignment.');if(state.user.role==='sld'&&['pending_advisor','pending_sld'].includes(club.status)&&!club.sld_review_started_at)club=(await api('/api/clubs/'+club.id+'/open-review',{revision:club.revision})).club;resetAutosave();if(club.status==='approved')clubProfile=structuredClone(club);else clubDraft=structuredClone(club);view='clubs';}else if(item.record_type==='club_report'){const report=(state.club_reports||[]).find(report=>report.id===item.record_id);if(!report)throw Error('This report is not available to your current assignment.');reportDraft=structuredClone(report);reportEditVersion=reportSavedVersion=0;reportRemote=null;view=reportDraft.type==='agm'?'agm':'weekly';}else if(item.record_type==='grant')view='clubs';else view='notifications';render({resetScroll:true,preserveFocus:false});document.querySelector('#main').focus({preventScroll:true});}

// PROPOSAL_SIGNATURE_START — ephemeral drawings; authenticated identities and server dates.
function signerIdentityMarkup(profile){return `<dl class="signer-identity"><div><dt>Name</dt><dd>${e(profile?.name||'Unavailable')}</dd></div><div><dt>Designation</dt><dd>${e(profile?.designation||'Unavailable')}</dd></div><div><dt>Department / club</dt><dd>${e(profile?.department||'Unavailable')}</dd></div><div><dt>Date</dt><dd>Recorded by the server after signing</dd></div></dl>`;}
function drawnSignatureMarkup(id){return `<div class="field full signature-field"><label for="${e(id)}">${requiredLabel('Draw your signature *')}</label><canvas class="signature" id="${e(id)}" width="1000" height="300" tabindex="0" aria-label="Drawn signature area. Use a mouse, touch screen or pen." aria-describedby="${e(id)}-help ${e(id)}-error"></canvas><small id="${e(id)}-help">Draw with a mouse, touch screen or pen. A click or blank image is not a signature. Drawings remain only on this page until submitted.</small><small class="error-text" id="${e(id)}-error" role="alert" hidden></small><button type="button" data-clear-drawing>Clear signature</button></div>`;}
function wireDrawnSignature(form){const canvas=form.querySelector('canvas'),ctx=canvas.getContext('2d'),error=form.querySelector('.error-text');let drawing=false,distance=0,moves=0,last=null;ctx.lineWidth=4;ctx.lineCap='round';const point=event=>{const rect=canvas.getBoundingClientRect();return [(event.clientX-rect.left)*canvas.width/rect.width,(event.clientY-rect.top)*canvas.height/rect.height];};const resetError=()=>{error.hidden=true;error.textContent='';canvas.removeAttribute('aria-invalid');};canvas.onpointerdown=event=>{if(event.button!==undefined&&event.button!==0)return;event.preventDefault();drawing=true;last=point(event);canvas.setPointerCapture(event.pointerId);ctx.beginPath();ctx.moveTo(...last);resetError();};canvas.onpointermove=event=>{if(!drawing)return;const next=point(event),segment=Math.hypot(next[0]-last[0],next[1]-last[1]);if(segment>0){distance+=segment;moves++;ctx.lineTo(...next);ctx.stroke();last=next;}};canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;form.querySelector('[data-clear-drawing]').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);drawing=false;distance=moves=0;last=null;resetError();};return ()=>{if(distance<12||moves<2){error.textContent='Draw your signature before continuing. A click or blank drawing cannot be submitted.';error.hidden=false;canvas.setAttribute('aria-invalid','true');canvas.focus();return null;}return canvas.toDataURL('image/png');};}
function showPreparedSignature(record){const container=document.querySelector('.proposal-review-wrap');container.querySelector('#proposal-preparer-panel')?.remove();const profile=record.preparer_profile||{name:state.user.name,designation:(proposalClub(record)?.committee||[]).find(member=>member.email===state.user.email)?.position,department:proposalClub(record)?.name};const panel=document.createElement('section');panel.className='panel review';panel.id='proposal-preparer-panel';panel.innerHTML=`<h2>Prepared by</h2><p class="help">One President or Vice President signs for this submitted version. Signing sends the proposal to the assigned advisor.</p><form id="proposal-preparer-form">${signerIdentityMarkup(profile)}${drawnSignatureMarkup('proposal-preparer-signature')}<div class="actions mt20"><button type="submit" class="primary">Sign & submit to advisor</button><button type="button" id="cancel-preparer-signing">Cancel signing</button></div></form>`;container.prepend(panel);const form=panel.querySelector('form'),signature=wireDrawnSignature(form),revision=record.revision;panel.querySelector('#cancel-preparer-signing').onclick=()=>panel.remove();form.onsubmit=event=>{event.preventDefault();action(async()=>{const png=signature();if(!png)return;await flushProposal();if(proposalRemote||proposalDraft!==record||record.revision!==revision)throw Error('This proposal changed after you opened signing. Review the saved version, then open Sign & submit again.');if(!proposalCanSubmit(record))throw Error('Your current assignment cannot sign and submit this proposal.');const result=await api(`/api/proposals/${record.id}/submit`,{revision:record.revision,settings_revision:state.settings?.revision,signature:png});proposalDraft=result.proposal;dirty=false;await refresh();render();notice('Signed proposal submitted for advisor review.');});};panel.querySelector('canvas').focus();}
function wireProposalStageReview(main,record){const form=main.querySelector('#proposal-stage-review');if(!form)return;const signature=wireDrawnSignature(form);const send=async actionName=>{if(proposalRemote)throw Error('A newer proposal exists. Load and review it before signing.');const comment=form.elements.review_comment.value.trim();if(actionName==='return'&&!comment){form.elements.review_comment.setCustomValidity('Give a reason for returning this proposal.');form.elements.review_comment.reportValidity();form.elements.review_comment.oninput=()=>form.elements.review_comment.setCustomValidity('');return;}const png=actionName==='approve'?signature():'';if(actionName==='approve'&&!png)return;const deficitReason=state.user.role==='sld'&&actionName==='approve'&&proposalBudgetAmount(record,'expenses')>proposalBudgetAmount(record,'revenue')?form.elements.deficit_approval_reason?.value.trim():'';if(state.user.role==='sld'&&actionName==='approve'&&proposalBudgetAmount(record,'expenses')>proposalBudgetAmount(record,'revenue')&&!deficitReason)throw Error('Give the SLD approval reason for this proposed deficit.');const confirmed=actionName==='approve'&&record.status==='pending_advisor';if(confirmed&&!await confirmSldSubmission({title:record.title,description:'Your signed endorsement sends this proposal to SLD.'}))return;const result=await api(`/api/proposals/${record.id}/review`,{confirm_submission:confirmed,deficit_approval_reason:deficitReason,action:actionName,comment,revision:record.revision,signature:png});await refresh();proposalDraft=result.proposal;render();notice(actionName==='return'?'Proposal returned for correction.':result.proposal.status==='approved'?'Signed event approved and added to the SLD calendar.':'Advisor endorsement recorded and sent to SLD.');};form.onsubmit=event=>{event.preventDefault();action(()=>send('approve'));};form.querySelector('#return-proposal').onclick=()=>action(()=>send('return'));}
function proposalSignerBlocks(p){const slots=p.signatures||{},stage=['draft','returned'].includes(p.status)?'preparer':p.status==='pending_advisor'?'advisor':p.status==='pending_sld'?'sld':null;return `<section class="panel"><h2>Signatures for this submitted version</h2><p class="help">One President or Vice President signs first, followed by the assigned Advisor, then SLD. Each card records one authenticated signer and server date.</p><div class="proposal-signer-slots">${[['preparer','1 · Prepared by'],['advisor','2 · Reviewed by Advisor'],['sld','3 · Reviewed by SLD']].map(([key,label])=>{const slot=slots[key],current=stage===key,assigned=key==='preparer'?p.preparer_profile:key===stage?p.reviewer_profile:null;return `<section class="${current?'current-signing-stage':''}"><h3>${e(label)}</h3><span class="badge">${slot?'Signed':current?'Current signing stage':'Awaiting previous stage'}</span>${slot?`<dl><div><dt>Name</dt><dd>${e(slot.name)}</dd></div><div><dt>Designation</dt><dd>${e(slot.designation)}</dd></div><div><dt>Department / club</dt><dd>${e(slot.department)}</dd></div><div><dt>Date</dt><dd>${e(localTime(slot.signed_at))}</dd></div><div><dt>Submitted version</dt><dd>${e(slot.revision)}</dd></div></dl>${slot.signature?`<img class="signature-history" src="${e(slot.signature)}" alt="Recorded ${e(label.toLowerCase())} signature">`:''}`:`<p class="muted mt16">${current?assigned?.name?e(assigned.name)+' · '+e(assigned.designation):key==='preparer'?'Club President or Vice President must sign and submit.':key==='advisor'?'Awaiting advisor signature':'Awaiting SLD signature':key==='preparer'?'Not signed and submitted':key==='advisor'?'Awaiting advisor signature':'Awaiting SLD signature'}</p>${current?'<p class="help">Signing date is recorded by the server when this stage is signed.</p>':''}`}</section>`;}).join('')}</div><p class="help">Current signatures appear here. Earlier submissions remain separate in the history below.</p></section>`;}
// PROPOSAL_SIGNATURE_END

let reportDraft=null,reportEditVersion=0,reportSavedVersion=0,reportSavePromise=null,reportSaveTimer,reportSaveError='',reportRemote=null,reportDirectoryRequest=0;
const reportEditableFields=['id','revision','creation_key','type','club_id','title','semester','date','start_time','end_time','venue','activity_kind','summary','objectives','attendance','minutes','decisions','next_meeting','new_committee','agenda','report_year','member_count','outgoing_activities','opening_speech','election_summary','adjournment'];
// REPORT_AUTOSAVE_START
function captureReport(){const form=document.querySelector('#club-report-form');if(!form||!reportDraft?.can_edit)return;for(const key of reportEditableFields){const input=form.elements.namedItem(key);if(input){if(key==='member_count'||key==='report_year'){const value=input.value.trim(),number=Number(value);reportDraft[key]=value===''?null:Number.isInteger(number)&&number>=0?number:value;}else reportDraft[key]=input.value;}}reportDraft.agenda=Array.from(form.querySelectorAll('[data-report-agenda-row]')).map(row=>Object.fromEntries(['start','end','agenda'].map(key=>[key,row.querySelector(`[data-agenda-${key}]`).value])));reportDraft.objectives=Array.from(form.querySelectorAll('[data-report-objective]')).map(input=>input.value);reportDraft.attendance=Array.from(form.querySelectorAll('[data-attendance-row]')).map(row=>({email:row.querySelector('[data-attendance-email]').value,name:row.querySelector('[data-attendance-name]').value,status:row.querySelector('select').value}));reportDraft.decisions=Array.from(form.querySelectorAll('[data-decision-row]')).map(row=>Object.fromEntries(['task','person','deadline'].map(key=>[key,row.querySelector(`[data-decision-${key}]`).value])));reportDraft.next_meeting=Object.fromEntries(['date','time','venue'].map(key=>[key,form.querySelector(`[name=next_meeting_${key}]`)?.value||'']));if(reportDraft.type==='agm')reportDraft.new_committee=Array.from(form.querySelectorAll('[data-new-committee-row]')).map(row=>({position:row.dataset.position,email:row.querySelector('input').value}));}
function reportSaveStatus(){return reportRemote?'A newer saved report is available. Load it before continuing.':reportSaveError?'Not saved: '+reportSaveError:reportSavePromise?'Saving report…':reportEditVersion>reportSavedVersion?'Changes waiting to save…':reportDraft?.id?'All report changes saved':'Start filling the report. Changes save automatically.';}
function updateReportSaveStatus(){const target=document.querySelector('#report-save-state');if(target)target.textContent=reportSaveStatus();const progress=document.querySelector('#report-completion');if(progress&&reportDraft?.progress){progress.textContent=reportDraft.progress.percent+'% complete · '+reportDraft.progress.completed+'/'+reportDraft.progress.total+' required sections';const list=document.querySelector('#report-checklist');if(list)list.innerHTML=reportChecklistItems(reportDraft);}const footer=document.querySelector('#report-submit-control');if(footer&&reportDraft?.can_edit){footer.innerHTML=reportDraft.can_sign&&reportDraft.signing_slot==='president'?'<button class="primary" type="button" id="report-sign-submit">Review & sign as President</button>':'<small>The club President signs and submits this report.</small>';footer.querySelector('button')?.addEventListener('click',()=>action(()=>openReportSigning(reportDraft,true)));}}
function markReportChanged(){reportEditVersion++;dirty=true;reportSaveError='';updateReportSaveStatus();clearTimeout(reportSaveTimer);reportSaveTimer=setTimeout(()=>flushReport().catch(error=>notice(error.message,true)),700);}
async function flushReport(){clearTimeout(reportSaveTimer);if(!reportDraft)return;captureReport();if(reportRemote)throw Error('A newer report exists. Your entries remain here. Load the saved version before continuing.');if(reportSavePromise)return reportSavePromise;if(reportEditVersion===reportSavedVersion&&reportDraft.id)return;if(!reportDraft.can_edit)throw Error('This report is not editable under your current assignment. Your entries remain here.');if(sessionExpired)throw sessionError();const draft=reportDraft;reportSavePromise=(async()=>{while(reportDraft===draft&&(reportEditVersion>reportSavedVersion||!draft.id)){const version=reportEditVersion,payload={};for(const key of reportEditableFields)if(key in draft)payload[key]=structuredClone(draft[key]);const result=await api('/api/club-reports',{report:payload}),saved=result.report;if(reportDraft!==draft)return;for(const key of ['id','revision','status','can_edit','can_sign','signing_slot','signer_profile','progress','return_context','next_action','signatures','history','created_at','updated_at','submitted_at','old_committee','can_apply_handover','handover_blocked_reason','can_rebase','report_year'])if(key in saved)draft[key]=saved[key];const index=(state.club_reports||[]).findIndex(report=>report.id===saved.id);if(index>=0)state.club_reports[index]=saved;else(state.club_reports??=[]).unshift(saved);reportSavedVersion=result.creation_replayed?version-1:version;if(typeof appendPhotoPanel==='function'&&document.querySelector('#club-report-form')&&!document.querySelector('#photo-evidence'))appendPhotoPanel(document.querySelector('#main'),{type:'club_report',id:draft.id,minimum:draft.type==='weekly'?2:1}).catch(showRequestError);dirty=reportEditVersion>reportSavedVersion;reportSaveError='';updateReportSaveStatus();if(!dirty)clearRecovery();}})();updateReportSaveStatus();try{await reportSavePromise;}catch(error){reportSaveError=error.message;dirty=true;if(error.status===409&&draft.id){const result=await api('/api/club-reports?club_id='+encodeURIComponent(draft.club_id));reportRemote=(result.reports||result.club_reports||[]).find(report=>report.id===draft.id)||null;showReportRemote();}throw error;}finally{reportSavePromise=null;updateReportSaveStatus();}}
// REPORT_AUTOSAVE_END
function reportRecovery(){if(!reportDraft)return null;const data={};for(const key of reportEditableFields)if(key in reportDraft)data[key]=structuredClone(reportDraft[key]);return data;}
function restoreReportRecovery(record,wasDirty){reportDraft=record?structuredClone(record):null;reportEditVersion=record&&wasDirty?1:0;reportSavedVersion=0;reportRemote=null;reportSaveError='';}
function syncReportRecovery(){if(!reportDraft)return;const remote=(state.club_reports||[]).find(report=>report.id===reportDraft.id);if(remote){if(remote.revision<reportDraft.revision)return;for(const key of ['status','can_edit','can_sign','signing_slot','signer_profile','progress','return_context','next_action','signatures','history','old_committee','can_apply_handover','handover_blocked_reason','can_rebase','report_year'])reportDraft[key]=remote[key];if(remote.revision>reportDraft.revision){reportRemote=remote;showReportRemote();}if(!remote.can_edit)document.querySelector('#club-report-form fieldset')?.setAttribute('disabled','');}else if(reportDraft.id){reportDraft.can_edit=false;reportSaveError='This report is no longer available to your current assignment.';}else reportDraft.can_edit=Boolean(state.clubs.find(club=>club.id===reportDraft.club_id)?.can_create_reports);}
function showReportRemote(){const main=document.querySelector('#main');if(!reportRemote||!main||main.querySelector('#report-remote'))return;const banner=document.createElement('section');banner.id='report-remote';banner.className='info';banner.innerHTML='<p>This report changed on the server. Your entries remain here. Load and review the latest saved version before editing or signing.</p><button type="button">Load latest saved report</button>';main.prepend(banner);banner.querySelector('button').onclick=()=>{if(dirty&&!confirm('Discard unsaved report entries and load the latest saved version?'))return;reportDraft=structuredClone(reportRemote);reportRemote=null;reportEditVersion=reportSavedVersion=0;dirty=false;clearRecovery();render();};}
function returnedRecordMarkup(record,kind){if(record.status!=='returned')return '';const history=record.history?.slice().reverse().find(entry=>entry.action==='return'),returned=record.return_context||history||{},actor=returned.name||returned.actor_name||returned.returned_by||returned.actor||history?.name||history?.actor||'Recorded reviewer',stage=returned.stage||returned.slot||history?.stage||'Review',time=returned.timestamp||returned.returned_at||history?.timestamp,reason=returned.comment||returned.reason||history?.comment||'Review the recorded corrections.';const next=record.status==='returned'&&!(record.can_edit??(kind==='proposal'?proposalCanEdit(record):kind==='club'?clubCanEdit(record):kind==='finance'?financialReportCanEdit():false))?'Await corrections from the assigned club committee. Review and sign when the corrected version reaches your stage.':record.next_action||((record.can_edit??(kind==='proposal'?proposalCanEdit(record):kind==='club'?clubCanEdit(record):kind==='finance'?financialReportCanEdit():false))?(kind==='report'?'Correct the report. The President must draw a fresh signature and submit it again.':kind==='proposal'?'Correct the proposal. The President or Vice President must sign and submit a new version.':kind==='withdrawal'?'Correct the request. The Treasurer must sign and submit a new version for President review.':kind==='completion'?'Correct the completion summary or photographs, then submit the saved record to SLD again.':kind==='finance'?'Correct the actual transactions and evidence, then submit the actual report to SLD again.':'Correct the registration, then submit it again for advisor review.'):'The assigned club committee must correct and resubmit this record. You can review the returned version here.');return `<section class="returned-context" role="status"><h2>Returned for correction</h2><p><strong>${e(actor)}</strong> · ${e(statusLabel(stage))}${time?' · '+e(localTime(time)):''}</p><blockquote>${e(reason)}</blockquote><p><strong>Your next action:</strong> ${e(typeof next==='string'?next.label||next:next.description||next.label||'Review the required corrections.')}</p></section>`;}
function reportsPage(type='weekly'){if(view==='agm')type='agm';const main=document.querySelector('#main');if(reportDraft){reportForm(main);return;}const clubs=visibleClubs().filter(club=>club.can_create_reports);agmReportYear??=Number(mytParts(state.server_time).year);main.innerHTML=`<header class="pagehead"><div><h1>${type==='agm'?'Annual AGM reports':'Weekly activities'}</h1><p>${type==='agm'?'Annual proceedings and committee handover.':'Completed meetings, training and club activities.'}</p></div></header>${type==='agm'?`<form id="agm-filters" class="filter-bar fields">${field('Report year','year',agmReportYear,'number','min="1900" max="2100" step="1" required')}${state.user.role==='sld'?selectField('Submission status','status',[['','All statuses'],['missing','Not submitted'],['pending','In review'],['draft','Draft'],['returned','Returned'],['approved','Approved']],agmTrackerStatus):''}</form>`:''}${state.user.role==='sld'&&type==='weekly'?weeklyTrackerMarkup():''}${state.user.role==='sld'&&type==='agm'?'<section class="profile-section" id="agm-tracking" aria-live="polite">Loading submission tracking…</section>':''}${clubs.length?`<form id="new-club-report" class="report-create-bar"><div>${selectField('Club','report_club',clubs.map(club=>[club.id,club.name]),clubs[0].id)}</div><button type="submit" class="primary">Create ${type==='agm'?'AGM':'weekly'} report</button></form>`:''}<section class="profile-section" id="club-report-list"></section>`;main.querySelector('#new-club-report')?.addEventListener('submit',event=>{event.preventDefault();const club=state.clubs.find(club=>club.id===event.target.elements.report_club.value),existing=type==='agm'&&(state.club_reports||[]).find(report=>report.type==='agm'&&report.club_id===club.id&&effectiveReportYear(report)===agmReportYear);if(existing){reportDraft=structuredClone(existing);notice('The annual report already exists. Continue this report.');}else reportDraft={creation_key:crypto.randomUUID(),club_id:club.id,type,report_year:type==='agm'?agmReportYear:null,title:'',semester:club.semester,date:'',start_time:'',end_time:'',venue:'',activity_kind:'meeting',summary:'',objectives:[],attendance:[],minutes:'',decisions:[],agenda:[],next_meeting:{date:'',time:'',venue:''},new_committee:mandatory.map(position=>({position,email:''})),can_edit:true,can_sign:false,status:'draft',old_committee:structuredClone(club.committee)};reportEditVersion=reportSavedVersion=0;reportRemote=null;render({resetScroll:true,preserveFocus:false});});const filters=main.querySelector('#agm-filters');if(filters)wireAutoFilters(filters,()=>{agmReportYear=Number(filters.elements.year.value);agmTrackerStatus=filters.elements.status?.value||'';updateReportList(type);if(state.user.role==='sld')return loadAgmTracking(main);});updateReportList(type);if(type==='weekly'&&state.user.role==='sld')wireWeeklyTracker(main);if(type==='agm'&&state.user.role==='sld')loadAgmTracking(main).catch(showRequestError);}
function reportLabel(type){return type==='agm'?'Annual general meeting report':'Weekly activity report';}
function selectField(label,name,options,value){return `<div class="field"><label for="${e(name)}">${e(label)}</label><select id="${e(name)}" name="${e(name)}">${options.map(([id,text])=>`<option value="${e(id)}" ${String(id)===String(value)?'selected':''}>${e(text)}</option>`).join('')}</select></div>`;}
function wireReportLinks(main){main.querySelectorAll('[data-open-report]').forEach(button=>button.onclick=()=>action(async()=>{await leaveCurrent();await refresh();const report=(state.club_reports||[]).find(report=>report.id===button.dataset.openReport);if(!report)throw Error('This report is no longer available to your assignment.');reportDraft=structuredClone(report);reportEditVersion=reportSavedVersion=0;reportRemote=null;view=reportDraft.type==='agm'?'agm':'weekly';render({resetScroll:true,preserveFocus:false});}));}
function reportField(label,key,type='text',extra=''){return field(label,key,reportDraft[key]??'',type,extra);}
function reportText(label,key){return textfield(label,key,reportDraft[key]||'');}
function reportForm(main){const r=reportDraft,club=state.clubs.find(club=>club.id===r.club_id),sports=club?.category?.toLowerCase().includes('sport');main.innerHTML=`<header class="pagehead"><div><button type="button" class="link" id="back-reports">← ${r.type==='agm'?'AGM reports':'Weekly activities'}</button><h1>${e(r.title||reportLabel(r.type))}</h1><p>${e(club?.name||'Assigned club')} · ${e(reportLabel(r.type))}</p></div><div class="actions">${badge(r.status)}${r.id?`<button type="button" id="report-export" ${state.auth.pdf_available||r.type==='weekly'&&sports?'':'disabled'}>Export PDF</button>${r.type==='agm'||!sports?'<button type="button" id="report-export-word">Export Word</button>':''}`:''}</div></header>${!state.auth.pdf_available&&(r.type==='agm'||!sports)?'<p class="help">PDF conversion is not configured. Export the original-format Word report for review.</p>':''}${returnedRecordMarkup(r,'report')}${r.can_rebase?`<section class="info"><h2>Outgoing committee changed</h2><p>${e(r.next_action||'Refresh the outgoing committee before signing this AGM report.')}</p><button type="button" id="rebase-agm">Refresh outgoing committee</button></section>`:''}<p class="help" id="report-completion">${r.progress?e(r.progress.percent)+'% complete · '+e(r.progress.completed)+'/'+e(r.progress.total)+' required sections':'Completeness updates after autosave.'}</p><details class="panel"><summary>Report completion checklist</summary><ul id="report-checklist">${reportChecklistItems(r)}</ul></details><div class="record-dates"><div><small>Created on server</small><strong>${e(r.created_at?localTime(r.created_at):'Not saved yet')}</strong></div><div><small>Last saved on server</small><strong>${e(r.updated_at?localTime(r.updated_at):'Not saved yet')}</strong></div><div><small>Submitted on server</small><strong>${e(r.submitted_at?localTime(r.submitted_at):'Not submitted')}</strong></div></div><form id="club-report-form"><fieldset class="plain-fieldset" ${r.can_edit?'':'disabled'}><section class="panel"><h2>Activity details</h2><div class="fields">${reportField('Report title *','title','text','required')}${r.type==='agm'?reportField('Report year *','report_year','number','required min="1900" max="2100" step="1"'):''}${reportField('Committee term / semester','semester','text','required')}${reportField('Actual activity / meeting date *','date','date','required')}${reportField('Start time *','start_time','time','required')}${reportField('End time *','end_time','time','required')}${reportField('Venue *','venue','text','required')}${selectField('Activity type','activity_kind',[['meeting','Meeting'],['training','Training'],['activity','Club activity']],r.activity_kind)}${reportText('Summary *','summary')}</div><h3 class="mt24">Objectives</h3>${(r.objectives||[]).map((text,index)=>`<div class="report-objective"><label for="report-objective-${index}">Objective ${index+1}</label><input id="report-objective-${index}" data-report-objective value="${e(text)}"><button type="button" data-remove-report-objective="${index}">Remove</button></div>`).join('')}<button type="button" id="add-report-objective">Add objective</button></section>${r.type==='weekly'?`<section class="panel"><h2>${sports?'Sports attendance':'Meeting minutes'}</h2><p class="help">${sports?'Record present and absent participants using university directory emails.':'Record the meeting discussion and agreed decisions. Attendance can also be recorded.'}</p>${reportText('Meeting minutes'+(sports?' (optional)':' *'),'minutes')}${attendanceEditor(r)}</section>`:`<section class="panel"><h2>AGM proceedings</h2><div class="fields">${reportText('Opening speech','opening_speech')}${reportText('Election summary *','election_summary')}${reportText('Outgoing committee activities *','outgoing_activities')}${reportText('Adjournment','adjournment')}${reportText('Meeting minutes','minutes')}${reportField('Member count','member_count','number','min="0" step="1"')}</div><h3 class="mt24">Outgoing committee · recorded snapshot</h3>${(r.old_committee||club?.committee||[]).map(member=>`<p>${e(member.position)} · ${e(member.name||member.email)}</p>`).join('')}<h3 class="mt24">New committee</h3>${mandatory.map(position=>{const member=(r.new_committee||[]).find(member=>member.position===position)||{};return `<div class="field mt16" data-new-committee-row data-position="${e(position)}"><label for="report-officer-${e(position.replace(/ /g,'-'))}">${e(position)} QIU email *</label><input id="report-officer-${e(position.replace(/ /g,'-'))}" type="email" list="report-directory" value="${e(member.email)}" required data-report-directory><small>${e(member.name||'Name and university ID resolved by the server')}</small></div>`;}).join('')}${attendanceEditor(r)}</section>`}${reportAgendaEditor(r)}<section class="panel"><h2>Decisions & follow-up</h2>${(r.decisions||[]).map((row,index)=>`<div class="fields report-decision" data-decision-row>${['task','person','deadline'].map(key=>`<div class="field"><label for="decision-${index}-${key}">${e(key==='person'?'Responsible person':statusLabel(key))}</label><input id="decision-${index}-${key}" data-decision-${key} type="${key==='deadline'?'date':'text'}" value="${e(row[key])}"></div>`).join('')}<button type="button" data-remove-decision="${index}">Remove decision</button></div>`).join('')}<button type="button" id="add-report-decision">Add decision</button><h3 class="mt24">Next meeting (optional)</h3><div class="fields">${['date','time','venue'].map(key=>field(statusLabel(key),'next_meeting_'+key,r.next_meeting?.[key]||'',key==='venue'?'text':key)).join('')}</div></section></fieldset><footer class="formfooter"><small id="report-save-state" role="status" aria-live="polite">${e(reportSaveStatus())}</small><span id="report-submit-control">${r.can_edit&&r.can_sign&&r.signing_slot==='president'?'<button class="primary" type="button" id="report-sign-submit">Review & sign as President</button>':r.can_edit?'<small>Save corrections here. The club President signs and submits.</small>':''}</span></footer></form><datalist id="report-directory"></datalist>${reportHandoverNotice(r)}${r.can_apply_handover?'<section class="panel"><h2>Approved AGM committee handover</h2><p>Apply the approved new committee to the club profile. This replaces current officer assignments and is recorded by the server.</p><button type="button" id="apply-agm-handover">Apply approved committee handover</button></section>':''}${reportSignerCards(r)}<div id="report-signing-panel"></div>${reportHistory(r)}`;main.querySelector('#back-reports').onclick=()=>navigate(r.type==='agm'?'agm':'weekly');main.querySelector('#report-export')?.addEventListener('click',()=>action(async()=>{await flushReport();await downloadFile(`/api/club-reports/${r.id}/export?format=pdf`,'QIU club report.pdf');}));main.querySelector('#report-export-word')?.addEventListener('click',()=>action(async()=>{await flushReport();await downloadFile(`/api/club-reports/${r.id}/export?format=docx`,'QIU club report.docx');}));const form=main.querySelector('#club-report-form');form.oninput=()=>{captureReport();markReportChanged();};form.onsubmit=event=>{event.preventDefault();action(flushReport);};const mutate=fn=>{captureReport();fn();markReportChanged();render();};main.querySelector('#add-report-objective').onclick=()=>mutate(()=>r.objectives.push(''));main.querySelectorAll('[data-remove-report-objective]').forEach(button=>button.onclick=()=>mutate(()=>r.objectives.splice(Number(button.dataset.removeReportObjective),1)));main.querySelector('#add-attendance').onclick=()=>mutate(()=>r.attendance.push({email:'',name:'',status:'present'}));main.querySelectorAll('[data-remove-attendance]').forEach(button=>button.onclick=()=>mutate(()=>r.attendance.splice(Number(button.dataset.removeAttendance),1)));main.querySelector('#add-report-decision').onclick=()=>mutate(()=>r.decisions.push({task:'',person:'',deadline:''}));main.querySelectorAll('[data-remove-decision]').forEach(button=>button.onclick=()=>mutate(()=>r.decisions.splice(Number(button.dataset.removeDecision),1)));main.querySelector('#report-sign-submit')?.addEventListener('click',()=>action(()=>openReportSigning(r,true)));main.querySelectorAll('[data-sign-report-slot]').forEach(button=>button.onclick=()=>action(()=>openReportSigning(r,r.signing_slot==='president')));main.querySelector('#add-report-agenda').onclick=()=>mutate(()=>{r.agenda??=[];r.agenda.push({start:'',end:'',agenda:''});});main.querySelectorAll('[data-remove-report-agenda]').forEach(button=>button.onclick=()=>mutate(()=>r.agenda.splice(Number(button.dataset.removeReportAgenda),1)));main.querySelector('#apply-agm-handover')?.addEventListener('click',()=>action(async()=>{const result=await api(`/api/club-reports/${r.id}/apply-handover`,{revision:r.revision,club_revision:club.revision});reportDraft=result.report;await refresh();render();notice('Approved committee handover applied.');}));main.querySelector('#rebase-agm')?.addEventListener('click',()=>action(async()=>{await flushReport();const result=await api(`/api/club-reports/${r.id}/rebase`,{revision:r.revision});reportDraft=result.report;reportEditVersion=reportSavedVersion=0;dirty=false;await refresh();render();notice('Outgoing committee refreshed. Review the report before signing.');}));wireReportDirectory(main,r);if(r.id)appendPhotoPanel(main,{type:'club_report',id:r.id,minimum:r.type==='weekly'?2:1}).catch(showRequestError);if(reportRemote)showReportRemote();}
function attendanceEditor(r){return `<h3 class="mt24">Attendance</h3>${(r.attendance||[]).map((row,index)=>`<div class="fields report-attendance" data-attendance-row><div class="field"><label for="attendance-${index}-email">University email</label><input id="attendance-${index}-email" type="email" list="report-directory" value="${e(row.email)}" data-attendance-email data-report-directory></div><div class="field"><label for="attendance-${index}-name">Directory name</label><input id="attendance-${index}-name" value="${e(row.name)}" data-attendance-name readonly></div><div class="field"><label for="attendance-${index}-status">Attendance</label><select id="attendance-${index}-status"><option value="present" ${row.status==='present'?'selected':''}>Present</option><option value="absent" ${row.status==='absent'?'selected':''}>Absent</option></select></div><button type="button" data-remove-attendance="${index}">Remove participant</button></div>`).join('')}<button type="button" id="add-attendance">Add participant</button>`;}
function wireReportDirectory(main,r){main.querySelectorAll('[data-report-directory]').forEach(input=>{let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{const value=input.value;if(value.length<2)return;try{const data=await api('/api/directory?q='+encodeURIComponent(value));if(!input.isConnected||reportDraft!==r||input.value!==value)return;main.querySelector('#report-directory').innerHTML=(data.people||[]).map(person=>`<option value="${e(person.email)}">${e(person.name)}</option>`).join('');}catch(error){showRequestError(error);}},300);});input.addEventListener('change',async()=>{const email=input.value;try{const data=await api('/api/directory?q='+encodeURIComponent(email));if(!input.isConnected||reportDraft!==r||input.value!==email)return;const person=data.people?.find(person=>person.email.toLowerCase()===email.toLowerCase());if(!person)throw Error('Choose a known university directory email. Ask SLD to update missing contacts.');const name=input.closest('[data-attendance-row]')?.querySelector('[data-attendance-name]');if(name)name.value=person.name;const officer=input.closest('[data-new-committee-row]');if(officer)officer.querySelector('small').textContent=person.name+' · '+(person.university_id||'University ID unavailable');captureReport();markReportChanged();}catch(error){showRequestError(error);}});});}
function reportSignerCards(r){const slots=r.signatures||{};return `<section class="panel"><h2>Signatures for this submitted version</h2><p class="help">Four distinct endorsements are required in this sequence. Each person signs using their authenticated identity. Corrections restart signatures for a new version.</p><div class="report-signer-cards">${[['president','1 · President'],['secretary','2 · Secretary'],['advisor','3 · Advisor'],['sld','4 · SLD']].map(([key,label])=>{const signer=slots[key],stage=['draft','returned'].includes(r.status)?'president':r.status?.replace('pending_',''),current=stage===key;return `<section><h3>${label}</h3><span class="badge">${signer?'Signed':current?'Current signing stage':'Awaiting previous stage'}</span>${signer?`<p class="mt16"><strong>${e(signer.name)}</strong><small class="block">${e(signer.designation)} · ${e(signer.department)}</small><small class="block">${e(localTime(signer.signed_at))} · Version ${e(signer.revision)}</small></p><img class="signature-history" src="${e(signer.signature)}" alt="Recorded ${e(key)} signature">`:current?`<p class="mt16">${e(r.signer_profile?.name||'Assigned '+key)}</p>${r.can_sign&&r.signing_slot===key?`<button type="button" data-sign-report-slot="${key}">Review & sign as ${e(statusLabel(key))}</button>`:'<p class="muted">Awaiting the assigned signer. Your current account cannot sign this stage.</p>'}`:'<p class="muted">No signature recorded for this stage.</p>'}</section>`;}).join('')}</div></section>`;}
async function openReportSigning(r,submit){await flushReport();if(submit&&r.progress?.checklist?.some(item=>!item.complete)){showReportValidation(r);return;}if(reportRemote)throw Error('Review the latest saved report before signing.');const target=document.querySelector('#report-signing-panel');target.innerHTML=`<section class="panel review"><h2>${submit?'President sign & submit':'Review & sign · '+e(statusLabel(r.signing_slot))}</h2>${signerIdentityMarkup(r.signer_profile)}<form id="report-signing-form">${submit?'':textfield('Review comment / required return reason','report_comment','')}${drawnSignatureMarkup('report-stage-signature')}<div class="actions mt20"><button type="submit" class="primary">${submit?'Sign & submit to Secretary':'Sign & approve this stage'}</button>${submit?'':'<button type="button" id="return-club-report">Return for correction</button>'}<button type="button" id="cancel-report-signing">Cancel</button></div></form></section>`;const form=target.querySelector('form'),read=wireDrawnSignature(form),revision=r.revision;const send=async actionName=>{if(reportDraft!==r||reportRemote||r.revision!==revision)throw Error('This report changed. Review the latest saved version before signing.');await flushReport();if(r.revision!==revision)throw Error('Corrections were saved after you opened signing. Review and open signing again.');const comment=form.elements.report_comment?.value.trim()||'';if(actionName==='return'&&!comment)throw Error('Give the committee a clear reason for returning the report.');const png=actionName==='approve'?read():'';if(actionName==='approve'&&!png)return;const confirmed=!submit&&actionName==='approve'&&r.signing_slot==='advisor';if(confirmed&&!await confirmSldSubmission({title:r.title,description:'Your signed endorsement sends this report to SLD.'}))return;const result=await api(`/api/club-reports/${r.id}/${submit?'submit':'review'}`,{confirm_submission:confirmed,revision:r.revision,signature:png,...(submit?{}:{action:actionName,comment})});reportDraft=result.report;reportEditVersion=reportSavedVersion=0;dirty=false;await refresh();render();notice(actionName==='return'?'Report returned with correction instructions.':'Signature recorded. The report moved to the next stage.');};form.onsubmit=event=>{event.preventDefault();action(()=>send('approve'));};form.querySelector('#return-club-report')?.addEventListener('click',()=>action(()=>send('return')));form.querySelector('#cancel-report-signing').onclick=()=>target.innerHTML='';form.querySelector('canvas').focus();}
function reportHandoverNotice(r){if(state.user.role!=='sld'||r.type!=='agm'||r.status!=='approved'||!r.handover_blocked_reason)return '';return `<section class="panel"><h2>Committee handover requires attention</h2><p>${e(r.handover_blocked_reason)}</p><p class="help">Resolve the listed assignment or review conflict before applying this approved committee handover.</p></section>`;}
function reportHistory(r){return `<details class="panel"><summary>Historical submissions & endorsements</summary>${(r.history||[]).map(entry=>`<article class="audit"><strong>${e(humanAction(entry.action))} · ${e(statusLabel(entry.stage||entry.slot||''))}</strong><p>${e(entry.signer?.name||entry.name||entry.actor)}${entry.comment?' · '+e(entry.comment):''}</p><small>${e(localTime(entry.signer?.signed_at||entry.timestamp))}</small>${entry.signer?.signature?`<img class="signature-history" src="${e(entry.signer.signature)}" alt="Historical signature, version ${e(entry.signer.revision)}">`:''}</article>`).join('')||'<p class="muted">No submitted signatures yet.</p>'}</details>`;}

let performanceYear=null,performanceMonth='',performanceClubId='',performanceRequest=0,performanceData=null,publicEventsRequest=0,publicEventDetail=null,assistantRequest=0;
function performanceCanView(){return state.user.role==='sld'||state.clubs.length>0||state.proposals.some(proposal=>proposal.status==='approved'&&(proposal.assigned_event_roles||[]).length>0);}
function performanceClubs(){const ids=new Set(state.proposals.filter(proposal=>proposal.status==='approved'&&(proposal.assigned_event_roles||[]).length).map(proposal=>proposal.club_id));return [...state.clubs,...(state.event_clubs||[]).filter(club=>ids.has(club.id)&&!state.clubs.some(assigned=>assigned.id===club.id))].map(club=>({id:club.id,name:club.name}));}
function performancePage(){const main=document.querySelector('#main');if(!performanceCanView()){main.innerHTML='<div class="info">Activity performance requires a current club or approved event committee assignment. Public upcoming events remain available in Upcoming events.</div>';return;}const clubs=performanceClubs();performanceClubId=clubs.some(club=>club.id===selectedClubId)?selectedClubId:'';performanceYear??=Number(mytParts(state.server_time).year);main.innerHTML=`<header class="pagehead"><div><div class="eyebrow">${state.user.role==='sld'?'SLD operational oversight':'Assigned club activities'}</div><h1>Club performance calendar</h1><p>Completed weekly meetings, training and AGMs, together with approved event schedules. This calendar tracks operations; financial balances remain in Financial records.</p></div></header><form id="performance-filters" class="panel"><div class="fields">${selectField('Activity scope','performance_club',[[ '',state.user.role==='sld'?'All clubs':'All assigned activities'],...clubs.map(club=>[club.id,club.name])],performanceClubId)}${field('Calendar year','performance_year',performanceYear,'number','min="2000" max="2100" required')}${selectField('Month','performance_month',[['','Whole year'],...Array.from({length:12},(_,index)=>[String(index+1),new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2026,index,1)))])],performanceMonth)}</div><p class="help mt16">${state.user.role==='sld'?'SLD can inspect every club.':'Only activities permitted by your current assignments are included. Event-only assignments show your assigned events, without other club reports or financial records.'}</p></form><div id="performance-results" aria-live="polite">Loading operational activity…</div>`;const filter=main.querySelector('form');wireAutoFilters(filter,()=>{performanceClubId=filter.elements.performance_club.value;performanceYear=Number(filter.elements.performance_year.value);performanceMonth=filter.elements.performance_month.value;return loadPerformance(main);});loadPerformance(main).catch(showRequestError);}
async function loadPerformance(main){const request=++performanceRequest,query=new URLSearchParams({year:String(performanceYear)});if(performanceMonth)query.set('month',performanceMonth);if(performanceClubId)query.set('club_id',performanceClubId);const data=await api('/api/performance?'+query);if(request!==performanceRequest||view!=='performance'||!main.isConnected)return;performanceData=data;const scope=main.querySelector('[name=performance_club]');if(scope){scope.innerHTML=`<option value="">${state.user.role==='sld'?'All clubs':'All assigned activities'}</option>`+(data.clubs||[]).map(club=>`<option value="${e(club.id)}" ${club.id===performanceClubId?'selected':''}>${e(club.name)}</option>`).join('');}const target=main.querySelector('#performance-results'),activities=data.activities||[];target.innerHTML=`<div class="overview-metrics"><div><strong>${activities.length}</strong><span>Recorded activities in this period</span></div><div><strong>${activities.filter(item=>item.occurrence==='completed').length}</strong><span>Completed activities</span></div><div><strong>${activities.filter(item=>['scheduled','ongoing'].includes(item.occurrence)).length}</strong><span>Upcoming / ongoing schedules</span></div></div><section class="panel"><h2>${e(performanceYear)}${performanceMonth?' · '+e(new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(performanceYear,Number(performanceMonth)-1,1)))):''} activity calendar</h2><p class="help">Each cell is a calendar day. Select a day to inspect meetings, AGMs and events. Arrow keys move between cells.</p>${performanceHeatmap(data.days||[],performanceYear,performanceMonth)}<div id="performance-day-details" class="mt24" aria-live="polite"><p class="muted">Select a day to view its operational records.</p></div></section><section class="panel"><h2>Activities in this period</h2>${activityRows(activities)}</section>`;wireTaskLinks(target);const cells=Array.from(target.querySelectorAll('[data-performance-day]'));cells.forEach((button,index)=>{button.onclick=()=>{cells.forEach(cell=>cell.setAttribute('aria-pressed',String(cell===button)));const day=data.days?.find(day=>day.date===button.dataset.performanceDay);target.querySelector('#performance-day-details').innerHTML=`<h3>${e(humanDate(button.dataset.performanceDay))}</h3>${activityRows(day?.activities||[])}`;wireTaskLinks(target.querySelector('#performance-day-details'));};button.onkeydown=event=>{const offset={ArrowDown:1,ArrowUp:-1,ArrowRight:7,ArrowLeft:-7,Home:-index,End:cells.length-index-1}[event.key];if(offset===undefined)return;event.preventDefault();const next=Math.max(0,Math.min(cells.length-1,index+offset));cells.forEach(cell=>cell.tabIndex=-1);cells[next].tabIndex=0;cells[next].focus();};});}
function performanceHeatmap(days,year,month=''){const begin=new Date(Date.UTC(year,month?Number(month)-1:0,1)),end=new Date(Date.UTC(year,month?Number(month):12,1)),length=Math.round((end-begin)/86400000),lookup=new Map(days.map(day=>[day.date,day]));return `<div class="heatmap-scroll"><div class="financial-heatmap operational-heatmap" role="group" aria-label="Operational club activity calendar">${Array.from({length},(_,index)=>{const date=new Date(begin.getTime()+index*86400000).toISOString().slice(0,10),day=lookup.get(date),count=Number(day?.count)||0,level=count?Math.min(4,Math.ceil(Math.log2(count+1))):0;return `<button type="button" class="heat-cell heat-${level}" data-performance-day="${date}" tabindex="${index===0?0:-1}" aria-label="${e(humanDate(date))}, ${count} activities" title="${e(humanDate(date))}: ${count} activities">${count?`<span class="sr-only">${count}</span>`:''}</button>`;}).join('')}</div></div><div class="heatmap-key"><small>No activity</small>${[0,1,2,3,4].map(level=>`<span class="heat-cell heat-${level}" aria-hidden="true"></span>`).join('')}<small>More activity</small></div>`;}
function activityRows(activities){return activities.length?activities.map(item=>`<article class="clubrow"><div><h3>${e(item.title)}</h3><p>${e(item.club_name)} · ${e(humanDate(item.date))} · ${e(statusLabel(item.kind))}</p>${badge(item.status)} <span class="badge">${e(statusLabel(item.occurrence))}</span></div>${safeTaskHref(item.href)?`<button type="button" data-task-href="${e(item.href)}">Open record</button>`:''}</article>`).join(''):'<p class="muted">No operational activities recorded for this date or period.</p>';}
// TASK_ROUTING_START
function safeTaskHref(href){if(typeof href!=='string'||!href.startsWith('/?')||href.includes('#'))return '';const query=new URLSearchParams(href.slice(2)),task=query.get('task'),id=query.get('id');if(!['proposal','club','report','event','finance','public-club','person','withdrawal','completion'].includes(task)||!id||id.length>100||!/^[A-Za-z0-9_-]+$/.test(id)||Array.from(query.keys()).some(key=>!['task','id'].includes(key)))return '';return '/?'+new URLSearchParams({task,id});}
async function openTaskHref(href,userAction=true){const safe=safeTaskHref(href);if(!safe)return false;const query=new URLSearchParams(safe.slice(2)),task=query.get('task'),id=query.get('id');const open=async()=>{await leaveCurrent();await refresh();clubDraft=clubProfile=proposalDraft=null;reportDraft=null;financeDraft=null;financeEventId=null;if(task==='withdrawal'||task==='completion'){await openOperation(task,id);return;}if(task==='public-club'){publicClubDetail=(await api('/api/public-clubs/'+encodeURIComponent(id))).club;view='browseclubs';}else if(task==='person'){publicStudentProfile=(await api('/api/public-students/'+encodeURIComponent(id))).profile;view='studentprofile';}else if(task==='finance'){const record=state.proposals.find(item=>item.id===id&&item.status==='approved');if(!record)throw Error('This financial record is not available under your current assignment.');await api(`/api/proposals/${id}/finance`);financeEventId=id;view='finance';}else if(task==='event'){publicEventDetail=await api('/api/public-events/'+encodeURIComponent(id));view='events';}else if(task==='proposal'){const record=state.proposals.find(item=>item.id===id);if(!record)throw Error('This proposal is not available under your current assignment.');resetProposalAutosave();proposalDraft=structuredClone(record);proposalStep=0;view='proposals';}else if(task==='club'){let record=state.clubs.find(item=>item.id===id);if(!record)throw Error('This club is not available under your current assignment.');if(state.user.role==='sld'&&['pending_advisor','pending_sld'].includes(record.status)&&!record.sld_review_started_at)record=(await api(`/api/clubs/${record.id}/open-review`,{revision:record.revision})).club;resetAutosave();if(record.status==='approved')clubProfile=structuredClone(record);else clubDraft=structuredClone(record);view='clubs';}else{const record=(state.club_reports||[]).find(item=>item.id===id);if(!record)throw Error('This report is not available under your current assignment.');reportDraft=structuredClone(record);reportEditVersion=reportSavedVersion=0;reportRemote=null;view=reportDraft.type==='agm'?'agm':'weekly';}render({resetScroll:true,preserveFocus:false});document.querySelector('#main').focus({preventScroll:true});};if(userAction)await action(open);else await open();return true;}
function wireTaskLinks(target){target.querySelectorAll('[data-task-href]').forEach(button=>button.onclick=()=>openTaskHref(button.dataset.taskHref));}
// TASK_ROUTING_END
function publicEventsPage(){const main=document.querySelector('#main');if(publicEventDetail){const event=publicEventDetail.event||publicEventDetail;main.innerHTML=`<header class="pagehead"><div><button class="link" type="button" id="back-public-events">← Upcoming events</button><h1>${e(event.title)}</h1><p>${e(event.club_name)}</p></div><span class="badge approved">Approved event</span></header><section class="panel"><h2>Event information</h2><dl class="signer-identity"><div><dt>When</dt><dd>${e(localTime(event.start_at))} – ${e(localTime(event.end_at))}</dd></div><div><dt>Venue</dt><dd>${e(event.venue)}</dd></div></dl><p>${e(event.summary||event.description||'')}</p><p class="help">This public listing includes approved event information. Committee documents and finances remain restricted to assigned accounts.</p></section>`;main.querySelector('#back-public-events').onclick=()=>{publicEventDetail=null;render({resetScroll:true,preserveFocus:false});};return;}main.innerHTML='<header class="pagehead"><div><div class="eyebrow">Campus events</div><h1>Upcoming approved events</h1><p>Explore upcoming club events approved by the Student Life Division.</p></div></header><section class="panel" id="public-event-list" aria-live="polite">Loading upcoming events…</section>';loadPublicEvents(main.querySelector('#public-event-list')).catch(showRequestError);}
async function loadPublicEvents(target){const request=++publicEventsRequest,data=await api('/api/public-events');if(request!==publicEventsRequest||!target.isConnected)return;target.innerHTML=(data.events||[]).map(event=>`<article class="clubrow"><div><h3>${e(event.title)}</h3><p>${e(event.club_name)} · ${e(localTime(event.start_at))}</p><small>${e(event.venue)}</small></div><button type="button" data-task-href="${e('/?task=event&id='+event.id)}">View event information</button></article>`).join('')||'<p class="muted">No upcoming approved events are currently published.</p>';wireTaskLinks(target);}
function assistantPage(){ensureChatOwner();const main=document.querySelector('#main');main.innerHTML=`<header class="pagehead"><div><h1>Student Life assistant</h1><p>${e(assistantScopeDescription())}</p></div></header><div id="assistant-capabilities" class="help"></div><section class="chat-workspace">${chatSurfaceMarkup('full')}</section>`;api('/api/assistant/capabilities').then(data=>{if(main.isConnected&&view==='assistant')main.querySelector('#assistant-capabilities').innerHTML=assistantCapabilitiesMarkup(data);}).catch(showRequestError);wireChatSurface(main,'full');loadChatHistory().catch(showRequestError);}
function assistantPublicOnly(){return state.user.role!=='sld'&&!state.clubs.length&&!state.proposals.length;}
function assistantQuestionPlaceholder(){return assistantPublicOnly()?'Which approved campus events are coming up?':'What needs my review? When is the next approved club event?';}
function assistantCapabilitiesMarkup(data){return `<h2>Information available to your account</h2><p>${e(data.scope||data.description||data.scope_description||assistantScopeDescription())}</p>${data.explanation?`<p class="help">${e(data.explanation)}</p>`:''}<p class="help">${data.generation_configured?'Answers can use the configured retrieval service. Sources remain restricted to your current permissions.':'Grounded record search is available. Generative answers are not configured; results come directly from permitted system records.'}</p>`;}
function assistantScopeDescription(){return state.user.role==='sld'?'SLD can search authorised club, event and report records across the university.':state.clubs.length||state.proposals.length?'You can search information for your currently assigned clubs and events, plus upcoming public approved events.':'You can search public upcoming approved events. Internal club documents and finances require a specific assignment.';}
function assistantAnswerMarkup(data){return `<section class="panel"><h2>${data.mode==='rag'?'Answer with retrieved sources':'Grounded record results'}</h2><div class="assistant-response">${e(data.answer)}</div><p class="help mt20">${data.mode==='grounded'?'This answer is based on permitted recorded information; no generative service was used.':'Review the linked records to confirm the answer.'} ${data.generated_at?e(localTime(data.generated_at)):''}</p><h3 class="mt24">Source records</h3>${(data.sources||[]).length?data.sources.map(source=>`<article class="source-record"><strong>${e(source.title)}</strong><small>${e(statusLabel(source.record_type))}</small>${safeTaskHref(source.href)?`<button type="button" data-task-href="${e(source.href)}">Open source</button>`:''}</article>`).join(''):'<p class="muted">No matching permitted records were found.</p>'}</section>`;}

function reportChecklistItems(r){return (r.progress?.checklist||[]).map(item=>`<li>${item.complete?'Complete':'Missing'} · ${e(item.label)}</li>`).join('')||'<li>The checklist updates after autosave.</li>';}
function showReportValidation(r){const main=document.querySelector('#main');main.querySelector('#report-validation')?.remove();const summary=document.createElement('section');summary.id='report-validation';summary.className='info validation-summary';summary.tabIndex=-1;summary.setAttribute('role','alert');summary.innerHTML=`<h2>Complete these report sections before signing</h2><ul>${r.progress.checklist.filter(item=>!item.complete).map(item=>`<li>${e(item.label)}</li>`).join('')}</ul><p>Your draft is saved. Correct the missing sections, then open Review & sign again.</p>`;main.prepend(summary);summary.focus();}
function reportAgendaEditor(r){return `<section class="panel"><h2>Meeting agenda / programme (optional)</h2>${(r.agenda||[]).map((row,index)=>`<div class="fields report-agenda" data-report-agenda-row>${['start','end','agenda'].map(key=>`<div class="field"><label for="report-agenda-${index}-${key}">${e(key==='agenda'?'Agenda item':statusLabel(key)+' time')}</label><input id="report-agenda-${index}-${key}" data-agenda-${key} type="${key==='agenda'?'text':'time'}" value="${e(row[key])}"></div>`).join('')}<button type="button" data-remove-report-agenda="${index}">Remove agenda item</button></div>`).join('')}<button type="button" id="add-report-agenda">Add agenda item</button></section>`;}
function reportQueueRows(){const reports=(state.club_reports||[]).filter(report=>(!selectedClubId||report.club_id===selectedClubId)&&report.can_sign&&!report.can_edit);return reports.length?reports.map(report=>`<article class="clubrow"><div><h3>${e(report.title)}</h3><p>${e(reportLabel(report.type))} · ${e(state.clubs.find(club=>club.id===report.club_id)?.name||'Assigned club')}</p>${badge(report.status)}<small class="block">Your stage: ${e(statusLabel(report.signing_slot))}</small></div><button type="button" data-open-report="${e(report.id)}">Review & sign report</button></article>`).join(''):'<p class="muted">No weekly or AGM reports awaiting your signature.</p>';}
function appendOperationsWidgets(main){if(view==='notifications'){main.insertAdjacentHTML('beforeend',`<section class="panel assistant-shortcut"><h2>Ask about your workflow</h2><p>${e(assistantScopeDescription())}</p><button type="button" id="inbox-assistant">Open Student Life assistant</button></section>`);main.querySelector('#inbox-assistant').onclick=()=>navigate('assistant');return;}if(!['dashboard','reviews'].includes(view))return;const reports=state.clubs.length||(state.club_reports||[]).length;main.insertAdjacentHTML('beforeend',`${reports?`<section class="panel"><header class="section-heading"><h2>Weekly & AGM report signatures</h2><button type="button" id="dashboard-reports">Weekly activities</button></header><div id="report-review-queue">${reportQueueRows()}</div></section>`:''}${view==='dashboard'?`<section class="panel"><header class="section-heading"><h2>${state.user.role==='sld'?'Operational performance':'Upcoming approved campus events'}</h2><button type="button" id="dashboard-operations">${state.user.role==='sld'?'Open performance calendar':'Browse events'}</button></header>${state.user.role==='sld'?'<p>Review completed weekly activities and AGMs, and approved event schedules across clubs. Filter the calendar by club, year and month.</p>':'<div id="dashboard-public-events" aria-live="polite">Loading upcoming events…</div>'+ (performanceCanView()?'<button type="button" id="dashboard-assigned-performance" class="mt20">Open assigned activity calendar</button>':'')}</section><section class="panel assistant-shortcut"><h2>Student Life assistant</h2><p>${e(assistantScopeDescription())}</p><button type="button" id="dashboard-assistant">Ask about your assigned work</button></section>`:''}`);main.querySelector('#dashboard-reports')?.addEventListener('click',()=>navigate('weekly'));main.querySelector('#dashboard-assigned-performance')?.addEventListener('click',()=>navigate('performance'));main.querySelector('#dashboard-assistant')?.addEventListener('click',()=>navigate('assistant'));main.querySelector('#dashboard-operations')?.addEventListener('click',()=>navigate(state.user.role==='sld'?'performance':'events'));wireReportLinks(main);const target=main.querySelector('#dashboard-public-events');if(target)loadPublicEvents(target).catch(showRequestError);}
function updateReportQueue(){const target=document.querySelector('#report-review-queue');if(target){target.innerHTML=reportQueueRows();wireReportLinks(target);}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&reportDraft&&dirty){persistRecovery();flushReport().catch(()=>{});}});

// UI_FILTERS_START
function humanDate(value){if(!value)return '';if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value)))return String(value);const date=new Date(String(value)+'T00:00:00+08:00');return Number.isNaN(date.getTime())?'Date unavailable':new Intl.DateTimeFormat('en-MY',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}).format(date);}
function humanPeriod(value){if(!/^\d{4}-\d{2}$/.test(String(value)))return String(value??'');const [year,month]=value.split('-').map(Number);return month<1||month>12?'Period unavailable':new Intl.DateTimeFormat('en-MY',{month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,month-1,1)));}
function wireAutoFilters(form,apply){let timer,last=JSON.stringify(Array.from(form.elements).filter(input=>input.name).map(input=>[input.name,input.value]));const run=async()=>{clearTimeout(timer);if(!form.isConnected||form.checkValidity&&!form.checkValidity())return;const next=JSON.stringify(Array.from(form.elements).filter(input=>input.name).map(input=>[input.name,input.value]));if(next===last)return;last=next;const position=captureUiPosition();try{await apply();}catch(error){last='';showRequestError(error,form);}finally{if(form.isConnected)restoreUiPosition(position);}};form.onsubmit=event=>{event.preventDefault();run();};form.onchange=run;form.oninput=event=>{if(event.target.tagName==='SELECT')return;clearTimeout(timer);timer=setTimeout(run,350);};}
// UI_FILTERS_END
let publicClubDetail=null,publicStudentProfile=null,publicClubSearch='',publicProfileRequest=0,agmReportYear=null,agmTrackerStatus='',agmTrackerRequest=0;
function publicClubsPage(){const main=document.querySelector('#main');if(publicClubDetail){publicClubProfileMarkup(main,publicClubDetail);return;}main.innerHTML=`<header class="pagehead"><div><h1>Browse clubs</h1><p>Explore QIU clubs, committees and published activities.</p></div></header><form id="public-club-filter" class="filter-bar">${field('Search clubs','q',publicClubSearch,'search')}</form><div id="public-club-results" aria-live="polite">Loading clubs…</div>`;const form=main.querySelector('form');wireAutoFilters(form,()=>{publicClubSearch=form.elements.q.value;return loadPublicClubs(main);});loadPublicClubs(main).catch(showRequestError);}
async function loadPublicClubs(main){const request=++publicProfileRequest,data=await api('/api/public-clubs?q='+encodeURIComponent(publicClubSearch));if(request!==publicProfileRequest||view!=='browseclubs'||!main.isConnected)return;main.querySelector('#public-club-results').innerHTML=`<div class="club-directory">${(data.clubs||[]).map(club=>`<article class="club-directory-card"><div class="club-directory-brand">${clubLogo(club)}<div><h2>${e(club.name)}</h2><small>${e(club.category)}</small></div></div><p>${e(club.bio||'Club profile')}</p><button type="button" data-task-href="${e('/?task=public-club&id='+club.id)}">View club profile</button></article>`).join('')||'<p class="muted">No published clubs match your search.</p>'}</div>`;wireTaskLinks(main);}
function clubLogo(club){const logo=safeImageUrl(club.logo);return logo?`<img class="public-club-logo" src="${e(logo)}" alt="${e(club.name)} logo">`:`<span class="public-club-logo logo-initials" aria-hidden="true">${e(initials(club.name))}</span>`;}
function publicClubProfileMarkup(main,club){main.innerHTML=`<header class="pagehead"><div><button type="button" class="link" id="back-club-directory">← Browse clubs</button><div class="public-profile-heading">${clubLogo(club)}<div><h1>${e(club.name)}</h1><p>${e(club.category)}</p></div></div></div></header><section class="profile-section"><h2>About the club</h2><p class="profile-bio">${e(club.bio)}</p></section><section class="profile-section"><h2>Committee & advisor</h2><div class="public-hierarchy">${(club.hierarchy||[]).map(person=>`<article>${personAvatar(person)}<div><small>${e(person.position)}</small><button class="person-name" type="button" data-task-href="${e('/?task=person&id='+person.profile_id)}">${e(person.name)}</button></div></article>`).join('')||'<p class="muted">No published committee profile.</p>'}</div></section>${publicHierarchyHistoryMarkup(club)}<section class="profile-section"><h2>Upcoming events</h2>${publicEventRows(club.upcoming_events||[])}</section><section class="profile-section"><h2>Upcoming club meetings</h2>${(club.upcoming_weekly_activities||[]).map(activity=>`<article class="published-summary"><h3>${e(activity.title)}</h3><p>${e(humanDate(activity.date))} · ${e(activity.time)} MYT · ${e(activity.venue)}</p><span class="badge">Scheduled</span></article>`).join('')||'<p class="muted">No upcoming meeting has been published.</p>'}</section><section class="profile-section"><h2>Completed weekly activities</h2>${(club.weekly_summaries||[]).map(summary=>`<article class="published-summary"><h3>${e(summary.title)}</h3><small>${e(humanDate(summary.date))} · ${e(statusLabel(summary.activity_kind))}</small><p>${e(summary.summary)}</p></article>`).join('')||'<p class="muted">No approved weekly summaries published yet.</p>'}</section>`;main.querySelector('#back-club-directory').onclick=()=>{publicClubDetail=null;render({resetScroll:true,preserveFocus:false});};wireTaskLinks(main);wireAvatarFallbacks(main);wirePublicHierarchyHistory(main,club);}
function publicEventRows(events){return events.length?events.map(event=>`<article class="clubrow"><div><h3>${e(event.title)}</h3><p>${e(localTime(event.start_at))}</p><small>${e(event.venue)}${event.roles?.length?' · '+e(event.roles.join(', ')):''}</small></div><button type="button" data-task-href="${e('/?task=event&id='+event.id)}">View event</button></article>`).join(''):'<p class="muted">No upcoming approved events.</p>';}
function publicStudentPage(){const main=document.querySelector('#main'),person=publicStudentProfile;if(!person){main.innerHTML='<p class="muted">Select a published student profile from a club.</p>';return;}main.innerHTML=`<header class="pagehead"><div class="public-profile-heading">${personAvatar(person)}<div><h1>${e(person.name)}</h1><p>${e(person.programme||'University profile')}</p></div></div><button type="button" id="student-browseclubs">Browse clubs</button></header><section class="profile-section"><h2>Club positions</h2>${(person.clubs||[]).map(club=>`<article class="clubrow"><div><h3>${e(club.name)}</h3><p>${e((club.positions||[]).join(' · '))}</p></div><button type="button" data-task-href="${e('/?task=public-club&id='+club.id)}">View club</button></article>`).join('')||'<p class="muted">No published club position.</p>'}</section><section class="profile-section"><h2>Upcoming event roles</h2>${publicEventRows(person.events||[])}</section>`;main.querySelector('#student-browseclubs').onclick=()=>{publicClubDetail=null;navigate('browseclubs');};wireTaskLinks(main);wireAvatarFallbacks(main);}
function selfProfileMarkup(profile){const staff=profile.role==='sld'||['staff','employee'].includes((profile.person_type||'').toLowerCase()),fields=[['Email',profile.email],['University ID',profile.university_id],['Person type',profile.person_type],...(staff?[['Department',profile.department]]:[['Programme',profile.programme],['Department',profile.department]]),['Profile source',profile.profile_source],['Directory status',profile.directory_status||state.directory?.status],['Captured at login',localTime(profile.captured_at||profile.profile_captured_at||profile.last_login_at)]];return `<header class="pagehead"><div><h1>My profile</h1><p>Your captured university identity and current roles.</p></div><span class="badge">${profile.preview?'Fictional test account':'University account'}</span></header><section class="profile-section"><div class="public-profile-heading">${personAvatar(profile)}<div><h2>${e(profile.name)}</h2><p>${e(profile.email)}</p></div></div><dl class="profile-grid">${fields.map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${e(value||'Not available')}</dd></div>`).join('')}</dl>${profile.profile_id?`<button type="button" data-task-href="${e('/?task=person&id='+profile.profile_id)}">View my public profile</button>`:''}</section><section class="profile-section"><h2>My club positions</h2>${(profile.clubs||[]).map(club=>`<article class="clubrow"><div><h3>${e(club.name)}</h3><p>${e((club.positions||[]).join(' · '))}</p></div><button type="button" data-task-href="${e('/?task=public-club&id='+club.id)}">View public club</button></article>`).join('')||'<p class="muted">No approved club assignment.</p>'}</section><section class="profile-section"><h2>My published event roles</h2>${publicEventRows(profile.events||[])}</section>`;}
async function loadSelfProfile(main){const owner=state.user.id,data=await api('/api/profile');if(!main.isConnected||view!=='profile'||state.user?.id!==owner)return;main.innerHTML=selfProfileMarkup(data.profile);wireTaskLinks(main);wireAvatarFallbacks(main);}
function effectiveReportYear(report){const year=Number(report.report_year??String(report.date||'').slice(0,4));return Number.isInteger(year)&&year>=1900&&year<=2100?year:Number(mytParts(state.server_time).year);}
function reportRows(reports){return reports.length?reports.map(report=>`<article class="clubrow"><div><h2>${e(report.title||reportLabel(report.type))}</h2><p>${e(state.clubs.find(club=>club.id===report.club_id)?.name||'Assigned club')} · ${e(humanDate(report.date||'Date not entered'))}${report.type==='agm'?' · '+e(effectiveReportYear(report)):''}</p>${badge(report.status)}${report.progress?`<small class="block">${e(report.progress.percent)}% complete</small>`:''}</div><button type="button" data-open-report="${e(report.id)}">${report.can_sign?'Review & sign':'Open report'}</button></article>`).join(''):'<p class="muted">No reports for this period.</p>';}
function updateReportList(type){const target=document.querySelector('#club-report-list');if(!target)return;target.innerHTML=reportRows((state.club_reports||[]).filter(report=>report.type===type&&(!selectedClubId||report.club_id===selectedClubId)&&(type!=='agm'||effectiveReportYear(report)===agmReportYear)));wireReportLinks(target);}
async function loadAgmTracking(main){const request=++agmTrackerRequest,data=await api('/api/agm-tracker?year='+agmReportYear);if(request!==agmTrackerRequest||!main.isConnected||view!=='agm')return;const clubs=(data.clubs||[]).filter(club=>(!selectedClubId||club.club_id===selectedClubId)&&trackingStatusMatches(club.status,agmTrackerStatus));main.querySelector('#agm-tracking').innerHTML=`<header class="section-heading"><h2>${e(agmReportYear)} submission tracking</h2><small>${clubs.length} clubs in this view</small></header><div class="table-scroll"><table class="data-table"><thead><tr><th>Club</th><th>Status</th><th>Report</th><th>Archive</th></tr></thead><tbody>${clubs.map(club=>`<tr><td>${e(club.club_name)}</td><td>${e(club.status==='missing'?'Not submitted':statusLabel(club.status))}</td><td>${club.report_id?`<button type="button" data-open-report="${e(club.report_id)}">Open report</button>`:'No annual AGM report'}</td><td><button type="button" data-annual-archive="${e(club.club_id)}">Download year ZIP</button></td></tr>`).join('')}</tbody></table></div>`;wireReportLinks(main.querySelector('#agm-tracking'));wireAnnualArchiveButtons(main.querySelector('#agm-tracking'));}

// CHAT_HISTORY_START
let chatSession=0,chatOwner=null,chatOpen=false,chatQuestion='',chatEntries=[],chatTotal=0,chatLimit=30,chatSending=false,chatError='',chatRequest=0,chatHistoryLoading=false;
function clearChatState(){chatSession++;chatOwner=null;chatOpen=false;chatQuestion='';chatEntries=[];chatTotal=0;chatLimit=30;chatSending=false;chatError='';chatHistoryLoading=false;chatRequest++;document.querySelector('#chat-dock')?.remove();}
function ensureChatOwner(){const owner=state.user?.id||null;if(chatOwner!==owner){clearChatState();chatOwner=owner;}return owner;}
function captureChatDraft(){const input=document.querySelector('[data-chat-question]');if(input&&chatOwner===state.user?.id)chatQuestion=input.value;}
function chatSurfaceMarkup(surface){return `<div class="chat-history" data-chat-history aria-live="polite">${chatHistoryMarkup()}</div><div class="chat-error" data-chat-error role="alert">${e(chatError)}</div><form data-chat-form><label for="chat-question-${surface}">Question</label><textarea id="chat-question-${surface}" data-chat-question required maxlength="1000" rows="${surface==='compact'?2:3}" placeholder="${e(assistantQuestionPlaceholder())}">${e(chatQuestion)}</textarea><div class="chat-form-actions"><small data-chat-status role="status">${chatSending?'Searching permitted records…':''}</small><button type="submit" class="primary" ${chatSending?'disabled':''}>${chatSending?'Searching…':'Send'}</button></div></form>`;}
function chatHistoryMarkup(){if(chatHistoryLoading)return '<p class="muted">Checking conversation access…</p>';if(!chatEntries.length)return '<p class="muted">Ask a question to start your conversation.</p>';return `<div class="chat-history-toolbar"><small>${chatTotal} saved conversations</small><button type="button" data-chat-clear>Delete history</button></div>${chatEntries.map(entry=>`<article class="chat-entry"><header><strong>${e(entry.available===false?'Conversation no longer available':entry.question||'Conversation no longer available')}</strong><button type="button" data-chat-delete="${e(entry.id)}" aria-label="Delete this conversation">Delete</button></header><small>${e(localTime(entry.created_at))}</small>${assistantAnswerMarkup(entry.response||{answer:'This conversation is unavailable.',sources:[],mode:'grounded'})}</article>`).join('')}${chatEntries.length<chatTotal?'<button type="button" data-chat-more>Load earlier conversations</button>':''}`;}
function renderChatDock(){ensureChatOwner();document.querySelector('#chat-dock')?.remove();if(!state.user)return;const dock=document.createElement('aside');dock.id='chat-dock';dock.className='chat-dock';dock.innerHTML=`${chatOpen&&view!=='assistant'?`<section class="compact-chat" id="compact-chat" aria-label="Student Life assistant"><header class="compact-chat-header"><strong>Student Life assistant</strong><div><button type="button" id="expand-chat" aria-label="Expand assistant">Expand</button><button type="button" id="close-chat" aria-label="Close assistant">×</button></div></header>${chatSurfaceMarkup('compact')}</section>`:''}<button type="button" id="chat-launcher" class="chat-launcher" aria-label="${chatOpen?'Close':'Open'} Student Life assistant" aria-expanded="${chatOpen&&view!=='assistant'}" aria-controls="compact-chat"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M21 11a8 8 0 0 1-8 8H7l-4 3V11a9 9 0 0 1 18 0Z"/><path d="M7 10h10M7 14h6"/></svg></button>`;document.body.append(dock);dock.querySelector('#chat-launcher').onclick=()=>{if(view==='assistant'){document.querySelector('[data-chat-question]')?.focus({preventScroll:true});return;}captureChatDraft();chatOpen=!chatOpen;renderChatDock();if(chatOpen){loadChatHistory().catch(chatFailure);dock.querySelector('[data-chat-question]')?.focus({preventScroll:true});document.querySelector('#compact-chat [data-chat-question]')?.focus({preventScroll:true});}};dock.querySelector('#close-chat')?.addEventListener('click',closeChat);dock.querySelector('#expand-chat')?.addEventListener('click',()=>{captureChatDraft();navigate('assistant');});dock.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();closeChat();}};if(chatOpen&&view!=='assistant')wireChatSurface(dock,'compact');}
function closeChat(){captureChatDraft();chatOpen=false;renderChatDock();document.querySelector('#chat-launcher')?.focus({preventScroll:true});}
function chatFailure(error){chatError=error.message||'The assistant could not connect. Retry your request.';updateChatSurfaces();}
function updateChatSurfaces(){document.querySelectorAll('[data-chat-history]').forEach(target=>{const scroll=target.scrollTop;target.innerHTML=chatHistoryMarkup();target.scrollTop=scroll;wireChatHistory(target);wireTaskLinks(target);});document.querySelectorAll('[data-chat-error]').forEach(target=>target.textContent=chatError);document.querySelectorAll('[data-chat-form]').forEach(form=>{const button=form.querySelector('[type=submit]');button.disabled=chatSending;button.textContent=chatSending?'Searching…':'Send';form.querySelector('[data-chat-status]').textContent=chatSending?'Searching permitted records…':'';});}
function wireChatSurface(container){container.querySelector('[data-chat-form]').onsubmit=event=>{event.preventDefault();captureChatDraft();sendChatQuestion().catch(chatFailure);};container.querySelector('[data-chat-question]').oninput=event=>chatQuestion=event.target.value;wireChatHistory(container);wireTaskLinks(container);}
function wireChatHistory(container){container.querySelectorAll('[data-chat-delete]').forEach(button=>button.onclick=()=>deleteChatHistory(button.dataset.chatDelete).catch(chatFailure));container.querySelector('[data-chat-clear]')?.addEventListener('click',()=>deleteChatHistory(null).catch(chatFailure));container.querySelector('[data-chat-more]')?.addEventListener('click',()=>{chatLimit+=30;loadChatHistory().catch(chatFailure);});}
async function loadChatHistory(){const owner=ensureChatOwner();if(!owner)return;const request=++chatRequest;chatHistoryLoading=true;chatEntries=[];updateChatSurfaces();try{const entries=[];let total=0,offset=0;do{const limit=Math.min(100,chatLimit-offset),data=await api('/api/assistant/history?offset='+offset+'&limit='+limit);if(owner!==state.user?.id||request!==chatRequest)return;total=data.total||0;const page=data.entries||[];entries.push(...page);offset+=page.length;if(!page.length)break;}while(offset<Math.min(total,chatLimit));chatEntries=entries;chatTotal=total;chatError='';}catch(error){if(owner!==state.user?.id||request!==chatRequest)return;throw error;}finally{if(owner===state.user?.id&&request===chatRequest){chatHistoryLoading=false;updateChatSurfaces();}}}
async function sendChatQuestion(){if(chatSending)return;const owner=ensureChatOwner(),session=chatSession,submittedDraft=chatQuestion,question=chatQuestion.trim();if(!owner||!question)return;chatSending=true;chatError='';updateChatSurfaces();try{await api('/api/assistant/query',{question,...(selectedClubId?{club_id:selectedClubId}:{})});if(owner!==state.user?.id||session!==chatSession)return;if(chatQuestion===submittedDraft){chatQuestion='';document.querySelectorAll('[data-chat-question]').forEach(input=>input.value='');}await loadChatHistory();}catch(error){if(owner!==state.user?.id||session!==chatSession)return;throw error;}finally{if(owner===state.user?.id&&session===chatSession){chatSending=false;updateChatSurfaces();}}}
async function deleteChatHistory(id){const owner=ensureChatOwner();await api('/api/assistant/history/delete',id?{id}:{all:true});if(owner!==state.user?.id)return;await loadChatHistory();}
function refreshVisibleChat(){ensureChatOwner();if((chatOpen||view==='assistant')&&!chatSending&&!chatHistoryLoading)loadChatHistory().catch(chatFailure);}
// CHAT_HISTORY_END
let weeklyTrackerStart='',weeklyTrackerStatus='',weeklyTrackerRequest=0;
function weeklyTrackerMarkup(){return `<form id="weekly-tracker-filters" class="filter-bar fields">${field('Week containing','week_start',weeklyTrackerStart,'date')}${selectField('Submission status','status',[['','All statuses'],['missing','No report recorded'],['pending','In review'],['draft','Draft'],['returned','Returned'],['approved','Approved']],weeklyTrackerStatus)}</form><section class="profile-section" id="weekly-tracking" aria-live="polite">Loading weekly tracking…</section>`;}
function trackingStatusMatches(status,filter){return !filter||(filter==='pending'?status.startsWith('pending_'):status===filter);}
function wireWeeklyTracker(main){const form=main.querySelector('#weekly-tracker-filters');wireAutoFilters(form,()=>{weeklyTrackerStart=form.elements.week_start.value;weeklyTrackerStatus=form.elements.status.value;return loadWeeklyTracking(main);});loadWeeklyTracking(main).catch(showRequestError);}
async function loadWeeklyTracking(main){const request=++weeklyTrackerRequest,data=await api('/api/weekly-tracker'+(weeklyTrackerStart?'?week_start='+weeklyTrackerStart:''));if(request!==weeklyTrackerRequest||!main.isConnected||view!=='weekly')return;weeklyTrackerStart=data.week_start;const input=main.querySelector('[name=week_start]');if(input&&document.activeElement!==input)input.value=data.week_start;const clubs=(data.clubs||[]).filter(club=>(!selectedClubId||club.club_id===selectedClubId)&&trackingStatusMatches(club.status,weeklyTrackerStatus));main.querySelector('#weekly-tracking').innerHTML=`<header class="section-heading"><h2>${e(humanDate(data.week_start))} – ${e(humanDate(data.week_end))}</h2><small>${clubs.length} clubs</small></header><p class="help">No report recorded means no activity report exists for this week. It does not indicate an overdue submission.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Club</th><th>Status</th><th>Reports</th><th>Approved</th><th>Review</th></tr></thead><tbody>${clubs.map(club=>`<tr><td>${e(club.club_name)}</td><td>${e(club.status==='missing'?'No report recorded':statusLabel(club.status))}</td><td>${club.report_count}</td><td>${club.approved_count}</td><td>${club.report_id?`<button type="button" data-open-report="${e(club.report_id)}">Open report</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`;wireReportLinks(main.querySelector('#weekly-tracking'));}

// SLD_CONFIRMATION_START
function confirmSldSubmission(options={}){const origin=document.activeElement;return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='confirmation-dialog';dialog.setAttribute('aria-labelledby','sld-confirm-title');dialog.setAttribute('aria-describedby','sld-confirm-description');let stage=1,settled=false;const close=value=>{if(settled)return;settled=true;dialog.close();dialog.remove();if(origin?.isConnected)origin.focus({preventScroll:true});resolve(value);};const paint=()=>{dialog.innerHTML=`<h2 id="sld-confirm-title">${stage===1?'Review your submission':'Confirm submission to SLD'}</h2><p><strong>${e(options.title||'Current saved version')}</strong></p><p id="sld-confirm-description">${e(stage===1?options.description||'Check this saved version and its supporting evidence.':'Send this version to SLD now? Changes will require a return for correction.')}</p><div class="actions"><button type="button" data-confirm-cancel>Keep editing</button><button type="button" class="primary" data-confirm-continue>${stage===1?'Continue':'Confirm & send to SLD'}</button></div>`;dialog.querySelector('[data-confirm-cancel]').onclick=()=>close(false);dialog.querySelector('[data-confirm-continue]').onclick=()=>{if(stage===1){stage=2;paint();}else close(true);};dialog.querySelector('[data-confirm-cancel]').focus({preventScroll:true});};dialog.addEventListener('cancel',event=>{event.preventDefault();close(false);});document.body.append(dialog);paint();dialog.showModal();});}
// SLD_CONFIRMATION_END

// OPERATION_AUTOSAVE_START
let operationDraft=null,operationKind='',operationInfo=null,operationEditVersion=0,operationSavedVersion=0,operationSavePromise=null,operationSaveTimer,operationError='',operationRemote=null,operationRequest=0;
const operationFields={withdrawal:['id','revision','creation_key','club_id','purpose','amount','bank_name','account_name','account_number','event_title','event_date','contact_name','contact_email','contact_phone','items','recipients'],completion:['id','revision','creation_key','proposal_id','summary']};
function operationRecovery(){return operationDraft?{kind:operationKind,draft:operationEditableDraft(operationDraft,operationKind)}:null;}
function captureOperation(){const form=document.querySelector('#operation-form');if(!form||!operationCanEdit())return;for(const key of operationFields[operationKind])if(!['id','revision','creation_key','club_id','proposal_id'].includes(key)&&form.elements[key])operationDraft[key]=form.elements[key].value;if(operationKind==='withdrawal')operationDraft.items=Array.from(form.querySelectorAll('[data-withdrawal-item]')).map(row=>Object.fromEntries(['description','price','quantity','payment_method'].map(key=>[key,row.querySelector('[data-item-'+key+']').value])));if(operationKind==='withdrawal')operationDraft.recipients=Array.from(form.querySelectorAll('[data-withdrawal-recipient]')).map(row=>Object.fromEntries(['name','email','contact','bank_name','account_name','account_number','amount'].map(key=>[key,row.querySelector('[data-payee-'+key+']').value])));}
function operationCanEdit(){return Boolean(!operationNeedsAccess&&operationDraft&&operationInfo&&(operationKind==='withdrawal'?operationDraft.can_edit:operationInfo.can_prepare&&['draft','returned'].includes(operationDraft.status||'draft'))&&!operationRemote);}
function markOperationChanged(){operationEditVersion++;dirty=true;operationError='';if(sessionExpired)persistRecovery();updateOperationSaveState();clearTimeout(operationSaveTimer);operationSaveTimer=setTimeout(()=>flushOperation().catch(error=>notice(error.message,true)),700);}
function updateOperationSaveState(){const target=document.querySelector('#operation-save-state');if(target)target.textContent=operationRemote?'A newer saved version is available. Reload before continuing.':operationError?'Not saved: '+operationError:operationSavePromise?'Saving…':operationEditVersion>operationSavedVersion?'Changes waiting to save…':operationDraft?.id?'All changes saved':'Changes save automatically.';}
async function flushOperation(){if(!operationDraft)return;if(operationNeedsAccess)await syncOperationAccess();if(operationRemote)throw Error('A newer saved version exists. Your entries are retained; check the saved version before continuing.');if(!operationCanEdit()){if(operationEditVersion>operationSavedVersion)throw Error('Your changes are retained but your current assignment cannot save this record.');return;}captureOperation();if(operationSavePromise){await operationSavePromise;return flushOperation();}clearTimeout(operationSaveTimer);if(operationDraft.id&&operationEditVersion===operationSavedVersion)return;const draft=operationDraft,kind=operationKind;operationSavePromise=(async()=>{while(operationDraft===draft&&(operationEditVersion>operationSavedVersion||!draft.id)){const version=operationEditVersion,body=operationRecovery().draft,data=await api(kind==='withdrawal'?'/api/withdrawals':'/api/event-completions',kind==='withdrawal'?{withdrawal:body}:{report:body}),saved=data.withdrawal||data.report;if(operationDraft!==draft)return;for(const [key,value] of Object.entries(saved))if(!operationFields[kind].includes(key)||['id','revision'].includes(key))draft[key]=value;operationSavedVersion=data.creation_replayed?version-1:version;dirty=operationEditVersion>operationSavedVersion;}operationError='';if(!dirty)clearRecovery();if(typeof refreshOperationActions==='function')refreshOperationActions();})();updateOperationSaveState();try{await operationSavePromise;}catch(error){operationError=error.message;dirty=true;if(error.status===409)operationRemote=true;if(error.status===401)persistRecovery();throw error;}finally{operationSavePromise=null;updateOperationSaveState();}}
// OPERATION_AUTOSAVE_END
function withdrawalsPage(){const main=document.querySelector('#main'),records=(state.withdrawals||[]).filter(record=>!selectedClubId||record.club_id===selectedClubId),clubs=visibleClubs().filter(club=>club.status==='approved'&&(club.can_create_withdrawals??club.committee.some(member=>member.email===state.user.email)));main.innerHTML=`<header class="pagehead"><div><h1>Fund withdrawals</h1><p>Signed authorisation, Finance evidence and transfer acknowledgement.</p></div></header>${clubs.length?`<form id="new-withdrawal" class="report-create-bar">${selectField('Club','club_id',clubs.map(club=>[club.id,club.name]),clubs[0].id)}<button type="submit" class="primary">Prepare withdrawal</button></form>`:''}<section class="profile-section">${records.map(record=>`<article class="clubrow"><div><h2>${e(record.purpose||'Fund withdrawal')}</h2><p>${e(state.clubs.find(club=>club.id===record.club_id)?.name)} · ${money(record.amount||0)}</p>${badge(record.status)}</div><button type="button" data-open-withdrawal="${e(record.id)}">Open withdrawal</button></article>`).join('')||'<p class="muted">No fund withdrawals recorded.</p>'}</section>`;main.querySelector('#new-withdrawal')?.addEventListener('submit',event=>{event.preventDefault();operationKind='withdrawal';operationNeedsAccess=false;operationDraft={creation_key:crypto.randomUUID(),club_id:event.target.elements.club_id.value,purpose:'',amount:'',bank_name:'',account_name:'',account_number:'',recipients:[],items:[],event_title:'',event_date:'',contact_name:'',contact_email:'',contact_phone:'',status:'draft',can_edit:true};operationInfo={};operationEditVersion=operationSavedVersion=0;operationRemote=null;view='withdrawal';render({resetScroll:true,preserveFocus:false});});main.querySelectorAll('[data-open-withdrawal]').forEach(button=>button.onclick=()=>action(()=>openOperation('withdrawal',button.dataset.openWithdrawal)));}
function completionListPage(){const main=document.querySelector('#main'),events=visibleProposals().filter(proposal=>proposal.status==='approved');main.innerHTML=`<header class="pagehead"><div><h1>Event completion</h1><p>Record the completed activity and upload its photographs for SLD review.</p></div></header><section class="profile-section">${events.map(event=>`<article class="clubrow"><div><h2>${e(event.title)}</h2><p>${e(humanDate(event.date))} · ${e(proposalClub(event)?.name)}</p></div><button type="button" data-event-completion="${e(event.id)}">Open completion record</button></article>`).join('')||'<p class="muted">No approved assigned events.</p>'}</section>`;wireCompletionButtons(main);}
function wireCompletionButtons(main){main.querySelectorAll('[data-event-completion]').forEach(button=>button.onclick=()=>action(()=>openOperation('completion',button.dataset.eventCompletion)));}
async function openOperation(kind,id){await leaveCurrent();clubDraft=clubProfile=proposalDraft=null;const data=await api(kind==='withdrawal'?'/api/withdrawals/'+id:'/api/proposals/'+id+'/completion');operationKind=kind;operationNeedsAccess=false;operationInfo=data;operationDraft=structuredClone(data.withdrawal||data.report||{proposal_id:id,creation_key:crypto.randomUUID(),summary:'',status:'draft'});operationEditVersion=operationSavedVersion=0;operationRemote=null;operationError='';view=kind==='withdrawal'?'withdrawal':'completion';render({resetScroll:true,preserveFocus:false});}
function operationPage(){const main=document.querySelector('#main'),record=operationDraft;if(operationNeedsAccess){main.innerHTML='<p role="status">Checking your current record access…</p>';syncOperationAccess().then(()=>{if(main.isConnected&&operationDraft===record)operationPage();}).catch(error=>{operationError=error.message;main.innerHTML='<p role="alert">'+e(error.message)+'</p>';});return;}if(!record){main.innerHTML='<p>Select a record to continue.</p>';return;}const withdrawal=operationKind==='withdrawal',editable=operationCanEdit(),club=state.clubs.find(club=>club.id===record.club_id);main.innerHTML=`<header class="pagehead"><div><button type="button" class="link" id="back-operations">← ${withdrawal?'Fund withdrawals':'Event completion'}</button><h1>${e(withdrawal?record.purpose||'Prepare fund withdrawal':operationInfo.title||'Event completion')}</h1><p>${e(club?.name||'Assigned event')} ${record.next_action?'· '+e(record.next_action):''}</p></div><div class="actions">${badge(record.status||'draft')}${record.id?'<button type="button" id="operation-export">Export PDF</button>':''}</div></header>${returnedRecordMarkup(withdrawal?record:{...record,can_edit:editable},withdrawal?'withdrawal':'completion')}<form id="operation-form"><fieldset class="plain-fieldset" ${editable?'':'disabled'}><section class="profile-section"><h2>${withdrawal?'Withdrawal details':'Completion summary'}</h2><div class="fields">${withdrawal?`${textfield('Purpose *','purpose',record.purpose)}${field('Amount (RM) *','amount',record.amount,'number','min="0.01" step="0.01"')}${field('Event title (if applicable)','event_title',record.event_title)}${field('Event date (if applicable)','event_date',record.event_date,'date')}}`:textfield('Completed activity summary *','summary',record.summary)}</div>${withdrawal?withdrawalItemsMarkup(record,editable):''}</section></fieldset>${editable?'<small id="operation-save-state" role="status">Changes save automatically.</small>':''}</form>${withdrawal?withdrawalActionsMarkup(record):`<section class="profile-section"><div class="actions">${operationInfo.can_prepare&&['draft','returned',undefined].includes(record.status)?'<button type="button" class="primary" id="completion-submit">Submit completion to SLD</button>':''}${operationInfo.can_review&&record.status==='pending_sld'?'<button type="button" class="primary" id="operation-review">Review completion</button>':''}</div></section>`}<div id="operation-signing"></div><div id="operation-photos"></div>${operationHistoryMarkup(record)}`;main.querySelector('#operation-form').oninput=()=>{captureOperation();markOperationChanged();};main.querySelector('#back-operations').onclick=()=>navigate(withdrawal?'withdrawals':'completionlist');main.querySelector('#operation-export')?.addEventListener('click',()=>action(async()=>{await flushOperation();await downloadFile(withdrawal?`/api/withdrawals/${record.id}/export?format=pdf`:`/api/event-completions/${record.id}/export`,'Record.pdf');}));main.querySelector('#completion-submit')?.addEventListener('click',()=>action(async()=>{await flushOperation();if(!await confirmSldSubmission({title:operationInfo.title,description:'Send the completion summary and event photos to SLD for approval.'}))return;const result=await api(`/api/event-completions/${record.id}/submit`,{revision:record.revision,confirm_submission:true});operationDraft=result.report;dirty=false;operationInfo=await api('/api/proposals/'+record.proposal_id+'/completion');render();}));main.querySelector('#operation-review')?.addEventListener('click',()=>action(()=>openOperationSigning('review')));if(withdrawal){wireWithdrawalActions(main,record);wireWithdrawalItems(main,record);}else appendPhotoPanel(main.querySelector('#operation-photos'),{type:'proposal',id:record.proposal_id,minimum:2});updateOperationSaveState();if(operationRemote)showOperationRemote(main);}
function operationHistoryMarkup(record){return record.history?.length?`<details class="profile-section"><summary>Signature & review history</summary>${record.history.map(entry=>`<article class="audit"><strong>${e(humanAction(entry.action||entry.stage||'Recorded'))}</strong><p>${e(entry.comment||'')}</p><small>${e(entry.name||entry.signer?.name||entry.actor)} · ${e(localTime(entry.timestamp||entry.signed_at))}</small>${entry.signer?.signature?`<img class="signature-history" src="${e(entry.signer.signature)}" alt="Recorded signature">`:''}</article>`).join('')}</details>`:'';}
function withdrawalActionsMarkup(record){return `<section class="profile-section" id="operation-actions"><h2>Authorisation & transfer</h2>${withdrawalSignerCards(record)}<p class="help">Treasurer → President → Advisor → SLD → Finance-signed evidence → All Approve → transfer receipt → SLD acknowledgement. This workflow does not post club income or expenses.</p>${record.transfer_due_at?`<p>Transfer deadline: <strong>${e(localTime(record.transfer_due_at))}</strong></p>`:''}<div class="actions">${record.can_sign?'<button type="button" class="primary" id="operation-review">Review & sign current stage</button>':''}${record.can_all_approve?'<button type="button" class="primary" id="withdrawal-all-approve">Sign All Approve</button>':''}${record.can_receive?'<button type="button" class="primary" id="withdrawal-receive" '+(record.receipt_document_id?'':'disabled')+'>Sign funds received</button>':''}${record.can_acknowledge?'<button type="button" class="primary" id="withdrawal-acknowledge">Acknowledge receipt</button>':''}${record.finance_document_id?'<button type="button" id="download-finance-document">Download Finance-signed document</button>':''}</div>${record.receipt_document_id?'<button type="button" id="download-fund-receipt">Download actual transfer receipt</button>':''}${record.can_upload_receipt?'<div class="field mt24"><label for="fund-receipt-file">Actual funds-received receipt *</label><input id="fund-receipt-file" type="file" accept="application/pdf,image/png,image/jpeg"><small>Upload the actual bank or transfer receipt before signing funds received. PDF, PNG or JPEG, up to 3 MB.</small></div>':''}${record.can_upload_finance?`<div class="field mt24"><label for="finance-signed-file">Finance-signed document *</label><input id="finance-signed-file" type="file" accept="application/pdf,image/png,image/jpeg"><small>Upload the actual Finance-signed document. Uploading is evidence, not a forged Finance signature.</small></div>`:''}</section>`;}
function wireWithdrawalActions(main,record){main.querySelector('#withdrawal-all-approve')?.addEventListener('click',()=>action(()=>openOperationSigning('all-approve')));main.querySelector('#withdrawal-receive')?.addEventListener('click',()=>action(()=>openOperationSigning('receive')));main.querySelector('#withdrawal-acknowledge')?.addEventListener('click',()=>action(async()=>{const result=await api(`/api/withdrawals/${record.id}/acknowledge`,{revision:record.revision});operationDraft=result.withdrawal;render();}));main.querySelector('#download-fund-receipt')?.addEventListener('click',()=>action(()=>downloadFile(`/api/withdrawals/${record.id}/receipt-document`,'Actual fund transfer receipt')));main.querySelector('#fund-receipt-file')?.addEventListener('change',event=>action(async()=>{const file=event.target.files[0];if(!file)return;if(file.size>3*1024*1024||!['application/pdf','image/png','image/jpeg'].includes(file.type))throw Error('Choose a PDF, PNG or JPEG receipt no larger than 3 MB.');const result=await api(`/api/withdrawals/${record.id}/receipt-document`,{revision:record.revision,filename:file.name,content_base64:await readReceipt(file)});operationDraft=result.withdrawal;render();}));main.querySelector('#download-finance-document')?.addEventListener('click',()=>action(()=>downloadFile(`/api/withdrawals/${record.id}/finance-document`,'Finance-signed document')));main.querySelector('#finance-signed-file')?.addEventListener('change',event=>action(async()=>{const file=event.target.files[0];if(!file)return;if(file.size>3*1024*1024||!['application/pdf','image/png','image/jpeg'].includes(file.type))throw Error('Choose a PDF or supported image no larger than 3 MB.');const result=await api(`/api/withdrawals/${record.id}/finance-document`,{revision:record.revision,filename:file.name,content_base64:await readReceipt(file)});operationDraft=result.withdrawal;render();}));}
async function openOperationSigning(route){await flushOperation();const record=operationDraft,revision=record.revision,withdrawal=operationKind==='withdrawal',target=document.querySelector('#operation-signing'),profile=record.signer_profile||operationInfo.reviewer_profile;target.innerHTML=`<section class="panel"><h2>${e(withdrawal?statusLabel(record.signing_slot||route):'SLD completion review')}</h2>${signerIdentityMarkup(profile)}<form id="operation-signing-form">${textfield('Review comment / required return reason','comment','')}${drawnSignatureMarkup('operation-signature')}<div class="actions mt20"><button type="submit" class="primary">Sign & confirm</button>${route==='review'&&(!withdrawal||record.status!=='draft')?'<button type="button" id="operation-return">Return for correction</button>':''}<button type="button" id="cancel-operation-signing">Cancel</button></div></form></section>`;const form=target.querySelector('form'),read=wireDrawnSignature(form);const send=async(actionName)=>{if(operationDraft!==record||operationRemote||record.revision!==revision)throw Error('This record changed. Reload and review it before signing.');const comment=form.elements.comment.value.trim();if(actionName==='return'&&!comment)throw Error('Give a reason for returning this record.');const signature=actionName==='approve'?read():'';if(actionName==='approve'&&!signature)return;const confirmed=withdrawal&&actionName==='approve'&&(record.signing_slot==='advisor'||route==='receive');if(confirmed&&!await confirmSldSubmission({title:record.purpose,description:route==='receive'?'Send the signed actual funds-received receipt to SLD for acknowledgement.':'Send this signed withdrawal request to SLD.'}))return;const actualRoute=withdrawal&&['draft','returned'].includes(record.status)&&route==='review'?'submit':route,body={revision:record.revision,signature,...(actualRoute==='review'?{action:actionName,comment}:{}),...(confirmed?{confirm_submission:true}:{}),...(actualRoute==='receive'?{receipt_document_id:record.receipt_document_id}:{})};const result=await api(`/${withdrawal?'api/withdrawals':'api/event-completions'}/${record.id}/${actualRoute}`,body);operationDraft=result.withdrawal||result.report;operationEditVersion=operationSavedVersion=0;dirty=false;await refresh();render();};form.onsubmit=event=>{event.preventDefault();action(()=>send('approve'));};form.querySelector('#operation-return')?.addEventListener('click',()=>action(()=>send('return')));form.querySelector('#cancel-operation-signing').onclick=()=>target.innerHTML='';form.querySelector('canvas').focus();}
function showOperationRemote(main){main.querySelector('#operation-remote')?.remove();const section=document.createElement('section');section.id='operation-remote';section.className='info';section.innerHTML='<h2>Saved version changed</h2><p>Your entries remain here. Check the latest saved record before continuing.</p><button type="button" id="reload-operation">Load saved version and discard my unsaved entries</button>';main.prepend(section);section.querySelector('button').onclick=()=>action(async()=>{const id=operationKind==='withdrawal'?operationDraft.id:operationDraft.proposal_id,data=await api(operationKind==='withdrawal'?'/api/withdrawals/'+id:'/api/proposals/'+id+'/completion');operationInfo=data;operationDraft=structuredClone(data.withdrawal||data.report);operationRemote=null;operationEditVersion=operationSavedVersion=0;dirty=false;render();});}

// PHOTO_EVIDENCE_START
let photoUploadPromise=null,photoUploadError='',photoRequest=0;
function photoQuery(target){return 'target_type='+encodeURIComponent(target.type)+'&target_id='+encodeURIComponent(target.id);}
function readPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error('The photo could not be read. Select it again.'));reader.readAsDataURL(file);});}
async function appendPhotoPanel(container,target){if(!target.id)return;let panel=container.querySelector('#photo-evidence');if(!panel){panel=document.createElement('section');panel.id='photo-evidence';panel.className='profile-section';container.append(panel);}const request=++photoRequest,data=await api('/api/photos?'+photoQuery(target));if(request!==photoRequest||!panel.isConnected)return;const minimum=data.minimum??target.minimum??0;panel.innerHTML=`<header class="section-heading"><h2>Activity photographs</h2><strong>${data.count??data.photos.length} / ${minimum} minimum</strong></header><p class="help">Upload ${minimum} distinct activity photos before submission. Photos become read-only during review.</p>${photoUploadError?'<p class="error-text" role="alert">'+e(photoUploadError)+'</p><button type="button" id="clear-photo-error">Clear failed upload</button>':''}${data.can_upload?'<div class="field"><label for="activity-photos">Upload photographs</label><input id="activity-photos" type="file" accept="image/png,image/jpeg,image/webp" multiple><small>JPEG, PNG or WebP, up to 2 MB per photograph.</small></div>':''}<div class="photo-grid">${(data.photos||[]).map(photo=>`<figure><img src="/api/photos/${encodeURIComponent(photo.id)}/file" alt="${e(photo.name)}" loading="lazy"><figcaption><strong>${e(photo.name)}</strong><small>${e(localTime(photo.uploaded_at))}</small><div class="actions"><button type="button" data-download-photo="${e(photo.id)}">Download</button>${data.can_upload?`<button type="button" data-delete-photo="${e(photo.id)}">Remove</button>`:''}</div></figcaption></figure>`).join('')||'<p class="muted">No activity photographs uploaded.</p>'}</div>${state.user.role==='sld'?'<button type="button" id="download-photo-zip">Download photo ZIP</button>':''}<small id="photo-upload-status" role="status"></small>`;panel.querySelector('#clear-photo-error')?.addEventListener('click',()=>{photoUploadError='';appendPhotoPanel(container,target).catch(showRequestError);});panel.querySelector('#activity-photos')?.addEventListener('change',event=>action(()=>mutatePhotos(container,target,Array.from(event.target.files))));panel.querySelectorAll('[data-delete-photo]').forEach(button=>button.onclick=()=>action(()=>mutatePhotos(container,target,[],button.dataset.deletePhoto)));panel.querySelectorAll('[data-download-photo]').forEach(button=>button.onclick=()=>action(()=>downloadFile('/api/photos/'+encodeURIComponent(button.dataset.downloadPhoto)+'/file','Activity photo')));panel.querySelector('#download-photo-zip')?.addEventListener('click',()=>action(()=>downloadFile('/api/photos/zip?'+photoQuery(target),'Activity photographs.zip')));}
async function mutatePhotos(container,target,files,removeId){if(photoUploadPromise)throw Error('Wait for the current photo upload.');for(const file of files)if(file.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose JPEG, PNG or WebP photos no larger than 2 MB each.');if(target.type==='club_report')await flushReport();else if(operationDraft)await flushOperation();const fields=Array.from(document.querySelectorAll('#club-report-form input,#club-report-form textarea,#club-report-form select,#operation-form input,#operation-form textarea,#operation-form select')).map(input=>({input,disabled:input.disabled}));fields.forEach(({input})=>input.disabled=true);photoUploadError='';photoUploadPromise=(async()=>{const items=removeId?[null]:files;for(const file of items){const revision=target.type==='club_report'?reportDraft?.revision:operationDraft?.revision,body=target.type==='club_report'?{target_revision:revision}:{completion_revision:revision};document.querySelector('#photo-upload-status').textContent=removeId?'Removing photograph…':'Uploading '+file.name+'…';const data=await api(removeId?'/api/photos/'+encodeURIComponent(removeId)+'/delete':'/api/photos',removeId?body:{...body,target_type:target.type,target_id:target.id,name:file.name,data_url:await readPhoto(file)});if(target.type==='club_report'&&reportDraft?.id===target.id&&data.target_revision)reportDraft.revision=data.target_revision;if(target.type==='proposal'&&operationDraft?.proposal_id===target.id&&data.completion_revision)operationDraft.revision=data.completion_revision;}await refresh();if(target.type==='club_report'&&reportDraft?.id===target.id){const fresh=(state.club_reports||[]).find(report=>report.id===target.id);if(fresh&&fresh.revision!==reportDraft.revision){reportRemote=fresh;showReportRemote();}else if(fresh){reportDraft.progress=fresh.progress;reportDraft.photo_evidence=fresh.photo_evidence;const label=document.querySelector('#report-completion');if(label)label.textContent=fresh.progress.percent+'% complete · '+fresh.progress.completed+'/'+fresh.progress.total+' required sections';}}if(container.isConnected)await appendPhotoPanel(container,target);})();try{await photoUploadPromise;}catch(error){photoUploadError=error.message;if(container.isConnected)await appendPhotoPanel(container,target).catch(()=>{});throw error;}finally{photoUploadPromise=null;fields.forEach(({input,disabled})=>{if(input.isConnected)input.disabled=disabled;});}}
// PHOTO_EVIDENCE_END

function proposalBudgetAmount(proposal,key){return (proposal[key]||[]).reduce((sum,row)=>sum+(Number(row.price)||0)*(Number(row.quantity)||0),0);}
function withdrawalItemsMarkup(record,editable){return `<section class="withdrawal-items"><h3>Requested items</h3>${(record.items||[]).map((item,index)=>`<div class="fields withdrawal-item" data-withdrawal-item="${index}">${['description','price','quantity','payment_method'].map(key=>`<div class="field"><label for="withdraw-item-${index}-${key}">${e({description:'Item',price:'Unit price (RM)',quantity:'Quantity',payment_method:'Payment method'}[key])}</label>${key==='payment_method'?`<select id="withdraw-item-${index}-${key}" data-item-${key}><option value="">Choose method</option>${['QIU to vendor','Student self purchase'].map(value=>`<option value="${e(value)}" ${item[key]===value?'selected':''}>${e(value)}</option>`).join('')}</select>`:`<input id="withdraw-item-${index}-${key}" data-item-${key} type="${['price','quantity'].includes(key)?'number':'text'}" ${['price','quantity'].includes(key)?'min="0" step="0.01"':''} value="${e(item[key])}">`}</div>`).join('')}${editable?`<button type="button" data-remove-withdraw-item="${index}">Remove item</button>`:''}</div>`).join('')}${editable?'<button type="button" id="add-withdraw-item">Add requested item</button>':''}<p class="help">Item totals and payee amounts must equal the requested withdrawal amount before submission.</p></section>${withdrawalRecipientsMarkup(record,editable)}`;}
function withdrawalRecipientsMarkup(record,editable){const recipients=record.recipients?.length?record.recipients:record.bank_name?[{name:record.contact_name,email:record.contact_email,contact:record.contact_phone,bank_name:record.bank_name,account_name:record.account_name,account_number:record.account_number,amount:record.amount}]:[];return `<section class="withdrawal-recipients"><h3>Payee accounts</h3>${recipients.map((recipient,index)=>`<fieldset class="plain-fieldset fields withdrawal-recipient" data-withdrawal-recipient="${index}"><legend>Payee ${index+1}</legend>${[['name','Individual / company name','text'],['email','Email address','email'],['contact','Contact number','tel'],['bank_name','Bank name','text'],['account_name','Account holder name','text'],['account_number','Account number','text'],['amount','Amount (RM)','number']].map(([key,label,type])=>`<div class="field"><label for="payee-${index}-${key}">${e(label)}</label><input id="payee-${index}-${key}" data-payee-${key} type="${type}" ${type==='number'?'min="0.01" step="0.01"':''} value="${e(recipient[key])}"></div>`).join('')}${editable?`<button type="button" data-remove-payee="${index}">Remove payee</button>`:''}</fieldset>`).join('')}${editable?'<button type="button" id="add-withdraw-payee">Add payee account</button>':''}</section>`;}
function wireWithdrawalItems(main,record){const mutate=callback=>{captureOperation();callback();markOperationChanged();const position=captureUiPosition();operationPage();restoreUiPosition(position);};main.querySelector('#add-withdraw-item')?.addEventListener('click',()=>mutate(()=>{record.items??=[];record.items.push({description:'',price:'',quantity:1,payment_method:''});}));main.querySelectorAll('[data-remove-withdraw-item]').forEach(button=>button.onclick=()=>mutate(()=>record.items.splice(Number(button.dataset.removeWithdrawItem),1)));main.querySelector('#add-withdraw-payee')?.addEventListener('click',()=>mutate(()=>{record.recipients??=[];record.recipients.push({name:'',email:'',contact:'',bank_name:'',account_name:'',account_number:'',amount:''});}));main.querySelectorAll('[data-remove-payee]').forEach(button=>button.onclick=()=>mutate(()=>record.recipients.splice(Number(button.dataset.removePayee),1)));}
function refreshOperationActions(){if(operationKind!=='withdrawal'||!operationDraft)return;const target=document.querySelector('#operation-actions');if(!target)return;target.outerHTML=withdrawalActionsMarkup(operationDraft);const main=document.querySelector('#main');wireWithdrawalActions(main,operationDraft);main.querySelector('#operation-review')?.addEventListener('click',()=>action(()=>openOperationSigning('review')));}
function handoverMarkup(club){const handover=club.committee_handover;if(!handover)return '';return `<section class="profile-section"><h2>Committee handover</h2><p>${club.handover_status==='completed'?'Incoming committee is now active.':'Outgoing and incoming committee access overlaps during the handover period. Incoming officers retain Pending titles until the period ends.'}</p><p>Handover ends <strong>${e(localTime(handover.ends_at))}</strong></p>${club.pending_incoming_committee?.length?`<ul>${club.pending_incoming_committee.map(member=>`<li>Pending ${e(member.position)} · ${e(member.name)}</li>`).join('')}</ul>`:''}</section>`;}
function wireAnnualArchiveButtons(main){main.querySelectorAll('[data-annual-archive]').forEach(button=>button.onclick=()=>action(()=>downloadFile('/api/clubs/'+encodeURIComponent(button.dataset.annualArchive)+'/annual-archive?year='+agmReportYear,'Club annual archive '+agmReportYear+'.zip')));}

let operationNeedsAccess=false,operationAccessPromise=null;
function restoreOperationRecovery(backup,wasDirty){if(!backup||!operationFields[backup.kind])return;operationKind=backup.kind;operationDraft=operationEditableDraft(backup.draft,operationKind);operationDraft.status='unavailable';operationDraft.can_edit=false;operationInfo=null;operationRemote=null;operationNeedsAccess=true;operationEditVersion=wasDirty?1:0;operationSavedVersion=0;}
async function syncOperationAccess(){if(!operationDraft||!state.user)return;const draft=operationDraft,owner=state.user.id,kind=operationKind;let data;if(kind==='completion')data=await api('/api/proposals/'+draft.proposal_id+'/completion');else if(draft.id)data=await api('/api/withdrawals/'+draft.id);else data={withdrawal:{can_edit:state.clubs.some(club=>club.id===draft.club_id&&club.can_create_withdrawals),status:'draft'}};if(operationDraft!==draft||state.user?.id!==owner)return;operationInfo=data;const saved=data.withdrawal||data.report;if(saved&&(!saved.revision||!draft.revision||saved.revision>=draft.revision)){for(const key of ['status','can_edit','can_sign','signing_slot','signer_profile','can_upload_finance','can_all_approve','can_receive','can_acknowledge','can_upload_receipt','receipt_document_id','receipt_document_sha256','next_action','history','signatures','finance_document_id','transfer_due_at'])if(key in saved)draft[key]=saved[key];if(saved.revision&&draft.revision&&saved.revision>draft.revision)operationRemote=saved;}operationNeedsAccess=false;if(!operationCanEdit())document.querySelector('#operation-form')?.querySelectorAll('input,select,textarea').forEach(input=>input.disabled=true);refreshOperationActions();}
function publicHierarchyHistoryMarkup(club){const history=club.hierarchy_history||[];return history.length?`<section class="profile-section"><h2>Annual committee history</h2><label for="public-hierarchy-year">Reporting year</label><select id="public-hierarchy-year"><option value="">Choose year</option>${history.map((entry,index)=>`<option value="${index}">${e(entry.year)}</option>`).join('')}</select><div id="public-historical-hierarchy" aria-live="polite"></div></section>`:'';}
function publicHierarchyRows(rows){return `<div class="public-hierarchy">${(rows||[]).map(person=>`<article>${personAvatar(person)}<div><small>${e(person.position)}</small>${person.profile_id?`<button type="button" class="person-name" data-task-href="${e('/?task=person&id='+person.profile_id)}">${e(person.name)}</button>`:`<strong>${e(person.name)}</strong>`}</div></article>`).join('')}</div>`;}
function wirePublicHierarchyHistory(main,club){const select=main.querySelector('#public-hierarchy-year');if(!select)return;select.onchange=()=>{const entry=(club.hierarchy_history||[])[Number(select.value)],target=main.querySelector('#public-historical-hierarchy');target.innerHTML=select.value===''?'':`<h3 class="mt24">${e(entry.year)} outgoing committee</h3>${publicHierarchyRows(entry.hierarchy)}<h3 class="mt24">Incoming committee</h3>${publicHierarchyRows(entry.incoming_hierarchy)}<small>Handover recorded ${e(localTime(entry.effective_at))}</small>`;wireTaskLinks(target);wireAvatarFallbacks(target);};}
async function loadFinancePhotoState(main,proposalId){const data=await api('/api/photos?target_type=proposal&target_id='+encodeURIComponent(proposalId));if(!main.isConnected||financeDraft?.proposal_id!==proposalId)return;const target=main.querySelector('#finance-photo-state');if(target)target.textContent=`${data.count??data.photos.length} event photos uploaded. At least 2 are required before SLD approves the actual financial report.`;}

function operationEditableDraft(record,kind){const fields=operationFields[kind],payload=Object.fromEntries(fields.filter(key=>key in record).map(key=>[key,structuredClone(record[key])]));for(const [key,rowFields] of Object.entries({items:['description','price','quantity','payment_method'],recipients:['name','email','contact','bank_name','account_name','account_number','amount']}))if(Array.isArray(payload[key]))payload[key]=payload[key].map(row=>Object.fromEntries(rowFields.filter(field=>field in row).map(field=>[field,structuredClone(row[field])])));return payload;}
function withdrawalSignerCards(record){return `<div class="report-signer-cards withdrawal-signatures">${[['treasurer','1 · Treasurer'],['president','2 · President'],['advisor','3 · Advisor'],['sld','4 · SLD'],['all_approve','5 · All Approve'],['received','6 · Treasurer funds received']].map(([key,label])=>{const signer=record.signatures?.[key];return `<section><h3>${label}</h3><span class="badge">${signer?'Signed':record.signing_slot===key?'Current stage':'Not signed'}</span>${signer?`<p>${e(signer.name)}</p><small>${e(signer.designation)} · ${e(signer.department)}</small><small class="block">${e(localTime(signer.signed_at))} · Version ${e(signer.revision)}</small><img class="signature-history" src="${e(signer.signature)}" alt="Recorded ${e(label)} signature">`:'<p class="muted">No signature recorded.</p>'}</section>`;}).join('')}</div>`;}

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&operationDraft&&dirty){persistRecovery();if(!sessionExpired)flushOperation().catch(()=>{});}});
window.addEventListener('pagehide',()=>{if(operationDraft&&dirty)persistRecovery();});
refresh().then(async()=>{view='dashboard';restoreRecovery();render();startPolling();if(state.user&&!dirty)await openTaskHref(location.search?'/'+location.search:'',false);}).catch(err=>{app.innerHTML='<main id="main" class="startup"><h1>Student Life is unavailable</h1><p id="start-error"></p><button id="retry">Try again</button></main>';document.querySelector('#start-error').textContent=err.message;document.querySelector('#retry').onclick=()=>location.reload();});
